--
-- Name: CONSTRAINT calendar_recurrence_month_day ON calendar_recurrence; Type: COMMENT; Schema: public; Owner: odoo
--

COMMENT ON CONSTRAINT calendar_recurrence_month_day ON public.calendar_recurrence IS 'CHECK (
        rrule_type != ''monthly''
        OR month_by != ''day''
        OR day >= 1 AND day <= 31
        OR weekday IN (''MON'', ''TUE'', ''WED'', ''THU'', ''FRI'', ''SAT'', ''SUN'') AND byday IN (''1'', ''2'', ''3'', ''4'', ''-1''))';


