nalBodyBank\\"/>\\n                                <t t-if=\\"journal_type == 'cash'\\" t-call=\\"JournalBodyBankCash\\"/>\\n                                <t t-if=\\"journal_type == 'sale' || journal_type == 'purchase'\\" t-call=\\"JournalBodySalePurchase\\"/>\\n                                <t t-if=\\"journal_type == 'general'\\" t-call=\\"JournalMiscelaneous\\"/>\\n                            </div>\\n                            <div class=\\"row mt-auto\\">\\n                                <t t-if=\\"['bank', 'cash', 'credit', 'sale'].includes(journal_type)                                             and !bank_unconfigured                                             or (journal_type == 'purchase' and !journal_is_empty)\\" t-call=\\"JournalBodyGraph\\"/>\\n                            </div>\\n                        </div>\\n                    </t>\\n\\n                    <t t-name=\\"JournalTop\\">\\n                        <span class=\\"d-flex d-flew-row align-items-baseline\\">\\n                            <a class=\\"fs-4 fw-bold\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'show_fetch_in_einvoices_button': show_fetch_in_einvoices_button, 'show_refresh_out_einvoices_status_button': show_refresh_out_einvoices_status_button}\\"><field name=\\"name\\"/></a>\\n                            <t t-if=\\"dashboard.show_company\\" groups=\\"base.group_multi_company\\">\\n                                <span class=\\"small fw-bold ms-1\\"> - <field name=\\"company_id\\"/></span>\\n                            </t>\\n                        </span>\\n                        <div t-att-title=\\"dashboard.title\\" t-if=\\"journal_type == 'purchase' &amp;&amp; record.alias_domain_id.raw_value &amp;&amp; !journal_is_empty\\">\\n                            <field name=\\"alias_id\\"/>\\n                        </div>\\n                        <t t-if=\\"journal_is_empty\\" name=\\"empty_journal_helper\\">\\n                            <span class=\\"text-muted\\" t-if=\\"journal_type == 'sale'\\">Get Paid online. Send electronic invoices.</span>\\n                            <span class=\\"text-muted\\" t-if=\\"journal_type == 'purchase'\\">Let artificial intelligence scan your bill. Pay easily.</span>\\n                            <span class=\\"text-muted\\" t-if=\\"journal_type == 'bank'\\">Connect your bank. Match invoices automatically.</span>\\n                        </t>\\n                    </t>\\n\\n                    <t t-name=\\"menu\\">\\n                        <t t-value=\\"JSON.parse(record.kanban_dashboard.raw_value)\\" t-set=\\"dashboard\\"/>\\n                        <t t-value=\\"record.type.raw_value\\" t-set=\\"journal_type\\"/>\\n                        <div class=\\"container\\">\\n                            <!-- For bank, cash and credit -->\\n                            <div t-if=\\"journal_type == 'bank' || journal_type == 'cash' || journal_type == 'credit'\\" class=\\"row\\" id=\\"bank_and_cash_container\\">\\n                                <div class=\\"col-4\\">\\n                                    <h5 id=\\"card_action_view_menus\\" class=\\"o_kanban_card_manage_title\\">\\n                                        <span role=\\"separator\\">View</span>\\n                                    </h5>\\n                                    <div id=\\"action_card_statements\\">\\n                                        <a t-if=\\"journal_type == 'bank'\\" role=\\"menuitem\\" type=\\"object\\" name=\\"open_action_with_context\\" context=\\"{'action_name': 'action_bank_statement_tree', 'search_default_journal': True}\\">Statements</a>\\n                                        <a t-if=\\"journal_type == 'credit'\\" role=\\"menuitem\\" type=\\"object\\" name=\\"open_action_with_context\\" context=\\"{'action_name': 'action_credit_statement_tree', 'search_default_journal': True}\\">Statements</a>\\n                                        <a t-if=\\"journal_type == 'cash'\\" role=\\"menuitem\\" type=\\"object\\" name=\\"open_action_with_context\\" context=\\"{'action_name': 'action_view_bank_statement_tree', 'search_default_journal': True}\\">Cash Registers</a>\\n                                    </div>\\n                                    <div>\\n                                        <a role=\\"menuitem\\" type=\\"object\\" name=\\"open_payments_action\\">Payments</a>\\n                                    </div>\\n                                </div>\\n\\n                                <div class=\\"col-4\\" groups=\\"account.group_account_basic\\" name=\\"kanban_manage_new\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span role=\\"separator\\">New</span>\\n                                    </h5>\\n                                    <div name=\\"bank_customer_payment\\">\\n                                        <a role=\\"menuitem\\" type=\\"object\\" name=\\"create_customer_payment\\">Customer Payment</a>\\n                                    </div>\\n                                    <div>\\n                                        <a role=\\"menuitem\\" type=\\"object\\" name=\\"create_supplier_payment\\">Vendor Payment</a>\\n                                    </div>\\n                                </div>\\n\\n                                <div class=\\"col-4\\" groups=\\"account.group_account_basic\\" name=\\"kanban_manage_reconciliation\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span role=\\"separator\\">Reconciliation</span>\\n                                    </h5>\\n                                    <div name=\\"action_card_reconciliation\\">\\n                                        <a type=\\"action\\" name=\\"328\\">Models</a>\\n                                    </div>\\n                                </div>\\n\\n                            </div>\\n\\n                            <!-- For purchase and sale -->\\n                            <div t-if=\\"journal_type == 'purchase' || journal_type == 'sale'\\" class=\\"row\\">\\n                                <div class=\\"col-4\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>View</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a t-if=\\"journal_type == 'sale'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_out_invoice_type'}\\">Invoices</a>\\n                                        <a t-if=\\"journal_type == 'purchase'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_in_invoice_type'}\\">Bills</a>\\n                                    </div>\\n                                    <div id=\\"sale_purchase_refund\\">\\n                                        <a t-if=\\"journal_type == 'sale'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_out_refund_type_non_legacy'}\\">Credit Notes</a>\\n                                        <a t-if=\\"journal_type == 'purchase'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_in_refund_type'}\\">Refund</a>\\n                                    </div>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_account_moves_all_a'}\\" groups=\\"account.group_account_user\\">Journal Items</a>\\n                                    </div>\\n                                </div>\\n\\n                                <div class=\\"col-4\\" groups=\\"account.group_account_invoice\\" name=\\"kanban_manage_new\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>New</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"action_create_new\\">\\n                                            <span t-if=\\"journal_type == 'sale'\\">Invoice</span>\\n                                            <span t-if=\\"journal_type == 'purchase'\\">Bill</span>\\n                                        </a>\\n                                    </div>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"action_create_new\\" context=\\"{'refund':True}\\">\\n                                            <span t-if=\\"journal_type == 'sale'\\">Credit Note</span>\\n                                            <span t-if=\\"journal_type == 'purchase'\\">Refund</span>\\n                                        </a>\\n                                    </div>\\n                                    <div t-if=\\"journal_type == 'sale'\\">\\n                                        <widget name=\\"account_file_uploader\\" title=\\"Upload Invoices\\" btnClass=\\"file_upload_kanban_action_a\\"/>\\n                                    </div>\\n                                </div>\\n\\n                                <div class=\\"col-4\\" name=\\"kanban_manage_reports\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>Reporting</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a t-if=\\"journal_type == 'sale'\\" type=\\"action\\" name=\\"338\\" groups=\\"account.group_account_readonly\\">Invoices Analysis</a>\\n                                        <a t-if=\\"journal_type == 'purchase'\\" type=\\"action\\" name=\\"337\\" groups=\\"account.group_account_readonly\\">Bills Analysis</a>\\n                                    </div>\\n                                </div>\\n                            </div>\\n\\n                            <!-- For general and situation -->\\n                            <div t-if=\\"journal_type == 'general' || journal_type == 'situation'\\" class=\\"row\\" groups=\\"account.group_account_readonly\\">\\n                                <div class=\\"col-4\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>View</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_journal_line'}\\">Journal Entries</a>\\n                                    </div>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_journal_line', 'search_default_unposted': 1}\\">Entries to Review</a>\\n                                    </div>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_account_moves_all_a'}\\" groups=\\"base.group_no_one\\">Journal Items</a>\\n                                    </div>\\n                                </div>\\n\\n                                <div class=\\"col-4\\" groups=\\"account.group_account_user\\" name=\\"kanban_manage_new\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>New</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"action_create_new\\">Journal Entry</a>\\n                                    </div>\\n                                </div>\\n\\n                                <div class=\\"col-4 o_kanban_manage_operations\\" groups=\\"account.group_account_user\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>Operations</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"action_post_all_entries\\">Post All Entries</a>\\n                                    </div>\\n                                </div>\\n                            </div>\\n\\n                            <div t-if=\\"widget.editable\\" class=\\"o_kanban_card_manage_settings row\\">\\n                                <field class=\\"col-8\\" name=\\"color\\" widget=\\"kanban_color_picker\\"/>\\n                            </div>\\n\\n                            <div groups=\\"account.group_account_manager\\" class=\\"row o_kanban_card_manage_settings\\">\\n                                <field name=\\"show_on_dashboard\\" widget=\\"boolean_favorite\\" class=\\"col-6\\"/>\\n                                <div class=\\"col-6 text-end\\">\\n                                    <a class=\\"dropdown-item\\" t-if=\\"widget.editable\\" type=\\"open\\">Configuration</a>\\n                                </div>\\n                            </div>\\n                        </div>\\n                    </t>\\n\\n                    <t t-name=\\"JournalChecks\\">\\n                        <div class=\\"row\\" t-if=\\"dashboard.has_unhashed_entries\\">\\n                            <a name=\\"show_unhashed_entries\\" type=\\"object\\" class=\\"text-warning\\">\\n                                Unhashed entries\\n                            </a>\\n                        </div>\\n                        <div class=\\"row\\" t-if=\\"dashboard.has_sequence_holes\\">\\n                            <a name=\\"show_sequence_holes\\" type=\\"object\\" class=\\"text-warning\\" t-att-title=\\"dashboard.title_has_sequence_holes\\">\\n                                Irregular Sequences\\n                            </a>\\n                        </div>\\n                    </t>\\n\\n                    <t t-name=\\"JournalMiscelaneous\\">\\n                        <div id=\\"dashboard_misc_left\\" class=\\"col mb-3 mb-sm-0\\">\\n                            <button id=\\"new_misc_entry_button\\" type=\\"object\\" name=\\"action_create_new\\" class=\\"btn btn-primary float-start me-1\\" groups=\\"account.group_account_user\\">\\n                                New\\n                            </button>\\n                        </div>\\n                        <div id=\\"dashboard_general_right\\" class=\\"col-auto\\">\\n                            <t t-if=\\"dashboard.number_draft &gt; 0\\">\\n                                <div class=\\"row\\" groups=\\"account.group_account_user\\">\\n                                    <div class=\\"col overflow-hidden text-start\\">\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'search_default_no_auto_post': 1, 'search_default_posted': 0, 'search_default_unposted': 1}\\"><t t-out=\\"dashboard.number_draft\\"/> To Validate</a>\\n                                    </div>\\n                                </div>\\n                            </t>\\n                            <t t-call=\\"JournalChecks\\"/>\\n                        </div>\\n                    </t>\\n\\n                    <t t-name=\\"JournalBodyBank\\">\\n                        <t t-call=\\"JournalBodyBankCash\\" t-name=\\"bank_configuration_placeholder\\"/>\\n                    </t>\\n\\n                    <t t-name=\\"JournalBodyBankCash\\">\\n                        <!-- On the left, display :\\n                            - A button corresponding to the bank_statements_source, if it wasn't configured, a button for each of them\\n                            - If there are statements to reconcile, a link to reconcile them -->\\n                        <div id=\\"dashboard_bank_cash_left\\" class=\\"col mb-3 mb-sm-0 o_kanban_primary_left\\">\\n                            <div name=\\"bank_cash_buttons\\" class=\\"d-flex gap-1\\">\\n                                <t t-set=\\"bank_requires_setup\\" t-value=\\"!record.bank_account_id.raw_value and ['undefined', 'online_sync'].includes(dashboard.bank_statements_source)\\"/>\\n                                <button t-if=\\"journal_type == 'bank' and bank_requires_setup\\" name=\\"action_configure_bank_journal\\" type=\\"object\\" class=\\"btn btn-primary\\" groups=\\"account.group_account_basic\\">Bank Setup</button>\\n                                <button id=\\"all_transactions_btn\\" type=\\"object\\" name=\\"open_action\\" class=\\"btn btn-primary\\">Transactions</button>\\n                            </div>\\n                        </div>\\n                        <!-- On the right, show other common informations/actions -->\\n                        <div id=\\"dashboard_bank_cash_right\\" class=\\"col-auto\\" name=\\"kanban_primary_right\\">\\n                            <div class=\\"row\\" t-if=\\"dashboard.nb_lines_bank_account_balance &gt; 0\\">\\n                                <div id=\\"dashboard_bank_cash_balance\\" class=\\"col overflow-hidden text-start\\">\\n                                    <span>Balance</span>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span dir=\\"ltr\\"><t t-out=\\"dashboard.account_balance\\"/></span>\\n                                </div>\\n                            </div>\\n                            <t t-if=\\"dashboard.has_at_least_one_statement and dashboard.account_balance != dashboard.last_balance and dashboard.last_statement_visible\\">\\n                                <div class=\\"row\\" name=\\"latest_statement\\">\\n                                    <div class=\\"col overflow-hidden text-start\\">\\n                                        <span title=\\"Latest Statement\\">Last Statement</span>\\n                                    </div>\\n                                    <div class=\\"col-auto text-end\\">\\n                                        <span dir=\\"ltr\\"><t t-out=\\"dashboard.last_balance\\"/></span>\\n                                    </div>\\n                                </div>\\n                            </t>\\n                            <div class=\\"row\\" t-if=\\"dashboard.nb_lines_outstanding_pay_account_balance &gt; 0\\">\\n                                <div id=\\"dashboard_bank_cash_outstanding_balance\\" class=\\"col overflow-hidden text-start\\">\\n                                    <a type=\\"action\\" name=\\"282\\" context=\\"{'search_default_unmatched': True, 'search_default_journal_id': id, 'search_default_state_posted': True, }\\">\\n                                        Payments\\n                                    </a>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span dir=\\"ltr\\"><t t-out=\\"dashboard.outstanding_pay_account_balance\\"/></span>\\n                                </div>\\n                            </div>\\n                            <div class=\\"row\\" t-if=\\"dashboard.nb_misc_operations &gt; 0\\" groups=\\"account.group_account_readonly\\">\\n                                <div id=\\"dashboard_bank_cash_misc_total\\" class=\\"col text-start\\">\\n                                    <a type=\\"object\\" name=\\"open_bank_difference_action\\" t-att-class=\\"dashboard.misc_class\\">Misc. Operations</a>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span dir=\\"ltr\\"><t t-out=\\"dashboard.misc_operations_balance\\"/></span>\\n                                </div>\\n                            </div>\\n                            <t t-call=\\"JournalChecks\\"/>\\n                            <t t-if=\\"dashboard.has_invalid_statements\\">\\n                                <div class=\\"row\\">\\n                                    <a type=\\"object\\" name=\\"open_invalid_statements_action\\" title=\\"Invalid Statement(s)\\" class=\\"text-danger\\">\\n                                        Invalid Statement(s)\\n                                    </a>\\n                                </div>\\n                            </t>\\n                        </div>\\n                    </t>\\n                    <t t-name=\\"JournalBodySalePurchase\\" id=\\"account.JournalBodySalePurchase\\">\\n                        <div class=\\"col mb-3 mb-sm-0\\" name=\\"kanban_primary_left\\">\\n                            <t t-if=\\"journal_type == 'sale'\\">\\n                                <button type=\\"object\\" name=\\"action_create_new\\" class=\\"btn btn-primary\\" groups=\\"account.group_account_invoice\\">\\n                                    New\\n                                </button>\\n                                <widget name=\\"account_onboarding\\" t-if=\\"journal_is_empty and dashboard['onboarding']\\"/>\\n                            </t>\\n                            <t t-if=\\"journal_type == 'purchase'\\">\\n                                <div t-if=\\"!journal_is_empty\\" class=\\"d-flex\\">\\n                                    <widget name=\\"account_file_uploader\\" btnClass=\\"btn btn-primary oe_kanban_action\\"/>\\n                                    <div class=\\"ms-1\\">\\n                                        <button type=\\"object\\" name=\\"action_create_new\\" class=\\"btn-secondary \\" groups=\\"account.group_account_invoice\\">New</button>\\n                                    </div>\\n                                </div>\\n                                <div t-else=\\"\\">\\n                                    <widget name=\\"account_file_uploader\\" btnClass=\\"btn btn-primary oe_kanban_action\\"/>\\n                                    <widget name=\\"bill_upload_guide\\"/>\\n                                </div>\\n                            </t>\\n                        </div>\\n                        <div t-if=\\"!journal_is_empty\\" class=\\"col-auto\\" name=\\"kanban_primary_right\\">\\n                            <div class=\\"row\\" t-if=\\"dashboard.number_draft\\">\\n                                <div class=\\"col overflow-hidden text-start\\">\\n                                    <a t-if=\\"journal_type == 'sale'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'search_default_draft': '1'}\\">\\n                                        <span title=\\"Invoices to Validate\\"><t t-out=\\"dashboard.number_draft\\"/> To Validate</span>\\n                                    </a>\\n                                    <a t-if=\\"journal_type == 'purchase'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'search_default_draft': '1'}\\">\\n                                        <span title=\\"Bills to Validate\\" id=\\"account_dashboard_purchase_draft\\"><t t-out=\\"dashboard.number_draft\\"/> To Validate</span>\\n                                    </a>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span dir=\\"ltr\\"><t t-out=\\"dashboard.sum_draft\\"/></span>\\n                                </div>\\n                            </div>\\n                            <div class=\\"row\\" t-if=\\"dashboard.number_waiting\\">\\n                                <div class=\\"col overflow-hidden text-start\\">\\n                                    <a t-if=\\"journal_type == 'sale'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'search_default_open': '1', 'search_default_posted': '1', 'journal_type': type}\\">\\n                                        <span><t t-out=\\"dashboard.number_waiting\\"/> Unpaid</span>\\n                                    </a>\\n                                    <a t-if=\\"journal_type == 'purchase'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'search_default_open': '1', 'search_default_posted': '1', 'journal_type': type}\\">\\n                                        <span title=\\"Bills to Pay\\" id=\\"account_dashboard_bills_to_pay\\"><t t-out=\\"dashboard.number_waiting\\"/> To Pay</span>\\n                                    </a>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span dir=\\"ltr\\"><t t-out=\\"dashboard.sum_waiting\\"/></span>\\n                                </div>\\n                            </div>\\n                            <div class=\\"row\\" t-if=\\"dashboard.number_late\\">\\n                                <div class=\\"col overflow-hidden text-start\\">\\n                                    <a t-if=\\"journal_type == 'sale'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'search_default_late': '1', 'search_default_posted': '1', 'journal_type': type}\\">\\n                                        <span title=\\"Invoices late\\" id=\\"account_dashboard_invoices_late\\">\\n                                            <t t-out=\\"dashboard.number_late\\"/> Late\\n                                        </span>\\n                                    </a>\\n                                    <a t-if=\\"journal_type == 'purchase'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'search_default_late': '1', 'search_default_posted': '1', 'journal_type': type}\\">\\n                                        <span title=\\"Bills Late\\" id=\\"account_dashboard_bills_late\\">\\n                                            <t t-out=\\"dashboard.number_late\\"/> Late\\n                                        </span>\\n                                    </a>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span dir=\\"ltr\\"><t t-out=\\"dashboard.sum_late\\"/></span>\\n                                </div>\\n                            </div>\\n                            <t t-if=\\"dashboard.number_to_check &gt; 0\\">\\n                                <div class=\\"row\\" groups=\\"account.group_account_user\\">\\n                                    <div class=\\"col overflow-hidden text-start\\">\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'search_default_to_check': True}\\"><t t-out=\\"dashboard.number_to_check\\"/> To Review</a>\\n                                    </div>\\n                                    <div class=\\"col-auto text-end\\">\\n                                        <span dir=\\"ltr\\"><t t-out=\\"dashboard.to_check_balance\\"/></span>\\n                                    </div>\\n                                </div>\\n                            </t>\\n                            <t t-call=\\"JournalChecks\\"/>\\n                        </div>\\n                    </t>\\n                    <t t-name=\\"JournalBodyGraph\\">\\n                        <field name=\\"kanban_dashboard_graph\\" t-att-graph_type=\\"['cash', 'bank', 'credit'].includes(journal_type) ? 'line' : 'bar'\\" widget=\\"dashboard_graph\\"/>\\n                    </t>\\n            </templates>\\n            </kanban>"}	<?xml version="1.0"?>\n<kanban can_open="0" highlight_color="color" class="o_account_kanban" js_class="account_dashboard_kanban">\n                <field name="id"/>\n                <field name="type"/>\n                <field name="color"/>\n                <field name="kanban_dashboard"/>\n                <field name="has_entries"/>\n                <field name="has_posted_entries"/>\n                <field name="activity_ids"/>\n                <field name="activity_state"/>\n                <field name="alias_domain_id"/>\n                <field name="bank_account_id"/>\n                <field name="show_fetch_in_einvoices_button"/>\n                <field name="show_refresh_out_einvoices_status_button"/>\n                <templates>\n                    <t t-name="card">\n                        <t t-value="JSON.parse(record.kanban_dashboard.raw_value)" t-set="dashboard"/>\n                        <t t-value="record.type.raw_value" t-set="journal_type"/>\n                        <t t-value="!record.has_entries.raw_value" t-set="journal_is_empty"/>\n                        <t t-set="bank_unconfigured" t-value="(journal_type == 'bank' or journal_type == 'credit')                                                                 and ['undefined', 'online_sync'].includes(dashboard.bank_statements_source)                                                                 and journal_is_empty"/>\n                        <t t-call="JournalTop"/>\n                        <div t-att-class="'mt-3 p-0 container-fluid' + (dashboard.is_sample_data ? ' o_sample_data' : '')">\n                            <div class="row">\n                                <t t-if="journal_type == 'bank' || journal_type == 'credit'" t-call="JournalBodyBank"/>\n                                <t t-if="journal_type == 'cash'" t-call="JournalBodyBankCash"/>\n                                <t t-if="journal_type == 'sale' || journal_type == 'purchase'" t-call="JournalBodySalePurchase"/>\n                                <t t-if="journal_type == 'general'" t-call="JournalMiscelaneous"/>\n                            </div>\n                            <div class="row mt-auto">\n                                <t t-if="['bank', 'cash', 'credit', 'sale'].includes(journal_type)                                             and !bank_unconfigured                                             or (journal_type == 'purchase' and !journal_is_empty)" t-call="JournalBodyGraph"/>\n                            </div>\n                        </div>\n                    </t>\n\n                    <t t-name="JournalTop">\n                        <span class="d-flex d-flew-row align-items-baseline">\n                            <a class="fs-4 fw-bold" type="object" name="open_action" context="{'show_fetch_in_einvoices_button': show_fetch_in_einvoices_button, 'show_refresh_out_einvoices_status_button': show_refresh_out_einvoices_status_button}"><field name="name"/></a>\n                            <t t-if="dashboard.show_company" groups="base.group_multi_company">\n                                <span class="small fw-bold ms-1"> - <field name="company_id"/></span>\n                            </t>\n                        </span>\n                        <div t-att-title="dashboard.title" t-if="journal_type == 'purchase' &amp;&amp; record.alias_domain_id.raw_value &amp;&amp; !journal_is_empty">\n                            <field name="alias_id"/>\n                        </div>\n                        <t t-if="journal_is_empty" name="empty_journal_helper">\n                            <span class="text-muted" t-if="journal_type == 'sale'">Get Paid online. Send electronic invoices.</span>\n                            <span class="text-muted" t-if="journal_type == 'purchase'">Let artificial intelligence scan your bill. Pay easily.</span>\n                            <span class="text-muted" t-if="journal_type == 'bank'">Connect your bank. Match invoices automatically.</span>\n                        </t>\n                    </t>\n\n                    <t t-name="menu">\n                        <t t-value="JSON.parse(record.kanban_dashboard.raw_value)" t-set="dashboard"/>\n                        <t t-value="record.type.raw_value" t-set="journal_type"/>\n                        <div class="container">\n                            <!-- For bank, cash and credit -->\n                            <div t-if="journal_type == 'bank' || journal_type == 'cash' || journal_type == 'credit'" class="row" id="bank_and_cash_container">\n                                <div class="col-4">\n                                    <h5 id="card_action_view_menus" class="o_kanban_card_manage_title">\n                                        <span role="separator">View</span>\n                                    </h5>\n                                    <div id="action_card_statements">\n                                        <a t-if="journal_type == 'bank'" role="menuitem" type="object" name="open_action_with_context" context="{'action_name': 'action_bank_statement_tree', 'search_default_journal': True}">Statements</a>\n                                        <a t-if="journal_type == 'credit'" role="menuitem" type="object" name="open_action_with_context" context="{'action_name': 'action_credit_statement_tree', 'search_default_journal': True}">Statements</a>\n                                        <a t-if="journal_type == 'cash'" role="menuitem" type="object" name="open_action_with_context" context="{'action_name': 'action_view_bank_statement_tree', 'search_default_journal': True}">Cash Registers</a>\n                                    </div>\n                                    <div>\n                                        <a role="menuitem" type="object" name="open_payments_action">Payments</a>\n                                    </div>\n                                </div>\n\n                                <div class="col-4" groups="account.group_account_basic" name="kanban_manage_new">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span role="separator">New</span>\n                                    </h5>\n                                    <div name="bank_customer_payment">\n                                        <a role="menuitem" type="object" name="create_customer_payment">Customer Payment</a>\n                                    </div>\n                                    <div>\n                                        <a role="menuitem" type="object" name="create_supplier_payment">Vendor Payment</a>\n                                    </div>\n                                </div>\n\n                                <div class="col-4" groups="account.group_account_basic" name="kanban_manage_reconciliation">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span role="separator">Reconciliation</span>\n                                    </h5>\n                                    <div name="action_card_reconciliation">\n                                        <a type="action" name="328">Models</a>\n                                    </div>\n                                </div>\n\n                            </div>\n\n                            <!-- For purchase and sale -->\n                            <div t-if="journal_type == 'purchase' || journal_type == 'sale'" class="row">\n                                <div class="col-4">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>View</span>\n                                    </h5>\n                                    <div>\n                                        <a t-if="journal_type == 'sale'" type="object" name="open_action" context="{'action_name': 'action_move_out_invoice_type'}">Invoices</a>\n                                        <a t-if="journal_type == 'purchase'" type="object" name="open_action" context="{'action_name': 'action_move_in_invoice_type'}">Bills</a>\n                                    </div>\n                                    <div id="sale_purchase_refund">\n                                        <a t-if="journal_type == 'sale'" type="object" name="open_action" context="{'action_name': 'action_move_out_refund_type_non_legacy'}">Credit Notes</a>\n                                        <a t-if="journal_type == 'purchase'" type="object" name="open_action" context="{'action_name': 'action_move_in_refund_type'}">Refund</a>\n                                    </div>\n                                    <div>\n                                        <a type="object" name="open_action" context="{'action_name': 'action_account_moves_all_a'}" groups="account.group_account_user">Journal Items</a>\n                                    </div>\n                                </div>\n\n                                <div class="col-4" groups="account.group_account_invoice" name="kanban_manage_new">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>New</span>\n                                    </h5>\n                                    <div>\n                                        <a type="object" name="action_create_new">\n                                            <span t-if="journal_type == 'sale'">Invoice</span>\n                                            <span t-if="journal_type == 'purchase'">Bill</span>\n                                        </a>\n                                    </div>\n                                    <div>\n                                        <a type="object" name="action_create_new" context="{'refund':True}">\n                                            <span t-if="journal_type == 'sale'">Credit Note</span>\n                                            <span t-if="journal_type == 'purchase'">Refund</span>\n                                        </a>\n                                    </div>\n                                    <div t-if="journal_type == 'sale'">\n                                        <widget name="account_file_uploader" title="Upload Invoices" btnClass="file_upload_kanban_action_a"/>\n                                    </div>\n                                </div>\n\n                                <div class="col-4" name="kanban_manage_reports">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>Reporting</span>\n                                    </h5>\n                                    <div>\n                                        <a t-if="journal_type == 'sale'" type="action" name="338" groups="account.group_account_readonly">Invoices Analysis</a>\n                                        <a t-if="journal_type == 'purchase'" type="action" name="337" groups="account.group_account_readonly">Bills Analysis</a>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- For general and situation -->\n                            <div t-if="journal_type == 'general' || journal_type == 'situation'" class="row" groups="account.group_account_readonly">\n                                <div class="col-4">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>View</span>\n                                    </h5>\n                                    <div>\n                                        <a type="object" name="open_action" context="{'action_name': 'action_move_journal_line'}">Journal Entries</a>\n                                    </div>\n                                    <div>\n                                        <a type="object" name="open_action" context="{'action_name': 'action_move_journal_line', 'search_default_unposted': 1}">Entries to Review</a>\n                                    </div>\n                                    <div>\n                                        <a type="object" name="open_action" context="{'action_name': 'action_account_moves_all_a'}" groups="base.group_no_one">Journal Items</a>\n                                    </div>\n                                </div>\n\n                                <div class="col-4" groups="account.group_account_user" name="kanban_manage_new">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>New</span>\n                                    </h5>\n                                    <div>\n                                        <a type="object" name="action_create_new">Journal Entry</a>\n                                    </div>\n                                </div>\n\n                                <div class="col-4 o_kanban_manage_operations" groups="account.group_account_user">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>Operations</span>\n                                    </h5>\n                                    <div>\n                                        <a type="object" name="action_post_all_entries">Post All Entries</a>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div t-if="widget.editable" class="o_kanban_card_manage_settings row">\n                                <field class="col-8" name="color" widget="kanban_color_picker"/>\n                            </div>\n\n                            <div groups="account.group_account_manager" class="row o_kanban_card_manage_settings">\n                                <field name="show_on_dashboard" widget="boolean_favorite" class="col-6"/>\n                                <div class="col-6 text-end">\n                                    <a class="dropdown-item" t-if="widget.editable" type="open">Configuration</a>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n\n                    <t t-name="JournalChecks">\n                        <div class="row" t-if="dashboard.has_unhashed_entries">\n                            <a name="show_unhashed_entries" type="object" class="text-warning">\n                                Unhashed entries\n                            </a>\n                        </div>\n                        <div class="row" t-if="dashboard.has_sequence_holes">\n                            <a name="show_sequence_holes" type="object" class="text-warning" t-att-title="dashboard.title_has_sequence_holes">\n                                Irregular Sequences\n                            </a>\n                        </div>\n                    </t>\n\n                    <t t-name="JournalMiscelaneous">\n                        <div id="dashboard_misc_left" class="col mb-3 mb-sm-0">\n                            <button id="new_misc_entry_button" type="object" name="action_create_new" class="btn btn-primary float-start me-1" groups="account.group_account_user">\n                                New\n                            </button>\n                        </div>\n                        <div id="dashboard_general_right" class="col-auto">\n                            <t t-if="dashboard.number_draft &gt; 0">\n                                <div class="row" groups="account.group_account_user">\n                                    <div class="col overflow-hidden text-start">\n                                        <a type="object" name="open_action" context="{'search_default_no_auto_post': 1, 'search_default_posted': 0, 'search_default_unposted': 1}"><t t-out="dashboard.number_draft"/> To Validate</a>\n                                    </div>\n                                </div>\n                            </t>\n                            <t t-call="JournalChecks"/>\n                        </div>\n                    </t>\n\n                    <t t-name="JournalBodyBank">\n                        <t t-call="JournalBodyBankCash" t-name="bank_configuration_placeholder"/>\n                    </t>\n\n                    <t t-name="JournalBodyBankCash">\n                        <!-- On the left, display :\n                            - A button corresponding to the bank_statements_source, if it wasn't configured, a button for each of them\n                            - If there are statements to reconcile, a link to reconcile them -->\n                        <div id="dashboard_bank_cash_left" class="col mb-3 mb-sm-0 o_kanban_primary_left">\n                            <div name="bank_cash_buttons" class="d-flex gap-1">\n                                <t t-set="bank_requires_setup" t-value="!record.bank_account_id.raw_value and ['undefined', 'online_sync'].includes(dashboard.bank_statements_source)"/>\n                                <button t-if="journal_type == 'bank' and bank_requires_setup" name="action_configure_bank_journal" type="object" class="btn btn-primary" groups="account.group_account_basic">Bank Setup</button>\n                                <button id="all_transactions_btn" type="object" name="open_action" class="btn btn-primary">Transactions</button>\n                            </div>\n                        </div>\n                        <!-- On the right, show other common informations/actions -->\n                        <div id="dashboard_bank_cash_right" class="col-auto" name="kanban_primary_right">\n                            <div class="row" t-if="dashboard.nb_lines_bank_account_balance &gt; 0">\n                                <div id="dashboard_bank_cash_balance" class="col overflow-hidden text-start">\n                                    <span>Balance</span>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span dir="ltr"><t t-out="dashboard.account_balance"/></span>\n                                </div>\n                            </div>\n                            <t t-if="dashboard.has_at_least_one_statement and dashboard.account_balance != dashboard.last_balance and dashboard.last_statement_visible">\n                                <div class="row" name="latest_statement">\n                                    <div class="col overflow-hidden text-start">\n                                        <span title="Latest Statement">Last Statement</span>\n                                    </div>\n                                    <div class="col-auto text-end">\n                                        <span dir="ltr"><t t-out="dashboard.last_balance"/></span>\n                                    </div>\n                                </div>\n                            </t>\n                            <div class="row" t-if="dashboard.nb_lines_outstanding_pay_account_balance &gt; 0">\n                                <div id="dashboard_bank_cash_outstanding_balance" class="col overflow-hidden text-start">\n                                    <a type="action" name="282" context="{'search_default_unmatched': True, 'search_default_journal_id': id, 'search_default_state_posted': True, }">\n                                        Payments\n                                    </a>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span dir="ltr"><t t-out="dashboard.outstanding_pay_account_balance"/></span>\n                                </div>\n                            </div>\n                            <div class="row" t-if="dashboard.nb_misc_operations &gt; 0" groups="account.group_account_readonly">\n                                <div id="dashboard_bank_cash_misc_total" class="col text-start">\n                                    <a type="object" name="open_bank_difference_action" t-att-class="dashboard.misc_class">Misc. Operations</a>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span dir="ltr"><t t-out="dashboard.misc_operations_balance"/></span>\n                                </div>\n                            </div>\n                            <t t-call="JournalChecks"/>\n                            <t t-if="dashboard.has_invalid_statements">\n                                <div class="row">\n                                    <a type="object" name="open_invalid_statements_action" title="Invalid Statement(s)" class="text-danger">\n                                        Invalid Statement(s)\n                                    </a>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                    <t t-name="JournalBodySalePurchase" id="account.JournalBodySalePurchase">\n                        <div class="col mb-3 mb-sm-0" name="kanban_primary_left">\n                            <t t-if="journal_type == 'sale'">\n                                <button type="object" name="action_create_new" class="btn btn-primary" groups="account.group_account_invoice">\n                                    New\n                                </button>\n                                <widget name="account_onboarding" t-if="journal_is_empty and dashboard['onboarding']"/>\n                            </t>\n                            <t t-if="journal_type == 'purchase'">\n                                <div t-if="!journal_is_empty" class="d-flex">\n                                    <widget name="account_file_uploader" btnClass="btn btn-primary oe_kanban_action"/>\n                                    <div class="ms-1">\n                                        <button type="object" name="action_create_new" class="btn-secondary " groups="account.group_account_invoice">New</button>\n                                    </div>\n                                </div>\n                                <div t-else="">\n                                    <widget name="account_file_uploader" btnClass="btn btn-primary oe_kanban_action"/>\n                                    <widget name="bill_upload_guide"/>\n                                </div>\n                            </t>\n                        </div>\n                        <div t-if="!journal_is_empty" class="col-auto" name="kanban_primary_right">\n                            <div class="row" t-if="dashboard.number_draft">\n                                <div class="col overflow-hidden text-start">\n                                    <a t-if="journal_type == 'sale'" type="object" name="open_action" context="{'search_default_draft': '1'}">\n                                        <span title="Invoices to Validate"><t t-out="dashboard.number_draft"/> To Validate</span>\n                                    </a>\n                                    <a t-if="journal_type == 'purchase'" type="object" name="open_action" context="{'search_default_draft': '1'}">\n                                        <span title="Bills to Validate" id="account_dashboard_purchase_draft"><t t-out="dashboard.number_draft"/> To Validate</span>\n                                    </a>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span dir="ltr"><t t-out="dashboard.sum_draft"/></span>\n                                </div>\n                            </div>\n                            <div class="row" t-if="dashboard.number_waiting">\n                                <div class="col overflow-hidden text-start">\n                                    <a t-if="journal_type == 'sale'" type="object" name="open_action" context="{'search_default_open': '1', 'search_default_posted': '1', 'journal_type': type}">\n                                        <span><t t-out="dashboard.number_waiting"/> Unpaid</span>\n                                    </a>\n                                    <a t-if="journal_type == 'purchase'" type="object" name="open_action" context="{'search_default_open': '1', 'search_default_posted': '1', 'journal_type': type}">\n                                        <span title="Bills to Pay" id="account_dashboard_bills_to_pay"><t t-out="dashboard.number_waiting"/> To Pay</span>\n                                    </a>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span dir="ltr"><t t-out="dashboard.sum_waiting"/></span>\n                                </div>\n                            </div>\n                            <div class="row" t-if="dashboard.number_late">\n                                <div class="col overflow-hidden text-start">\n                                    <a t-if="journal_type == 'sale'" type="object" name="open_action" context="{'search_default_late': '1', 'search_default_posted': '1', 'journal_type': type}">\n                                        <span title="Invoices late" id="account_dashboard_invoices_late">\n                                            <t t-out="dashboard.number_late"/> Late\n                                        </span>\n                                    </a>\n                                    <a t-if="journal_type == 'purchase'" type="object" name="open_action" context="{'search_default_late': '1', 'search_default_posted': '1', 'journal_type': type}">\n                                        <span title="Bills Late" id="account_dashboard_bills_late">\n                                            <t t-out="dashboard.number_late"/> Late\n                                        </span>\n                                    </a>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span dir="ltr"><t t-out="dashboard.sum_late"/></span>\n                                </div>\n                     