448	16	\N	1	1	Calendar Invitation Page for anonymous users	\N	calendar.invitation_page_anonymous	qweb	calendar/views/calendar_templates.xml	primary	{"en_US": "<t name=\\"Calendar Invitation Page for anonymous users\\" t-name=\\"calendar.invitation_page_anonymous\\">\\n        <t t-call=\\"web.layout\\">\\n            <t t-set=\\"head\\">\\n                <t t-call-assets=\\"web.assets_frontend\\" t-js=\\"false\\"/>\\n            </t>\\n\\n            <div class=\\"container\\">\\n                <div class=\\"o_logo\\">\\n                    <img t-attf-src=\\"/web/binary/company_logo?company={{ company.id }}\\" alt=\\"Logo\\"/>\\n                </div>\\n\\n                <div class=\\"card\\">\\n                    <div class=\\"card-header\\">\\n                        <h2>Calendar Invitation <small><t t-esc=\\"event.name\\"/></small></h2>\\n                    </div>\\n                    <div class=\\"card-body\\">\\n                        <div class=\\"clearfix mb16 d-flex justify-content-between align-content-center flex-grow-0\\">\\n                            <div class=\\"col d-flex\\">\\n                                <form t-if=\\"attendee.state != 'accepted'\\" method=\\"POST\\" t-attf-action=\\"/calendar/meeting/accept?{{keep_query()}}\\" class=\\"me-1 d-inline-block\\">\\n                                    <input type=\\"hidden\\" name=\\"csrf_token\\" t-att-value=\\"request.csrf_token()\\"/>\\n                                    <button type=\\"submit\\" role=\\"button\\" class=\\"btn btn-primary btn-block\\">Accept</button>\\n                                </form>\\n                                <form t-if=\\"attendee.state != 'declined'\\" method=\\"POST\\" t-attf-action=\\"/calendar/meeting/decline?{{keep_query()}}\\" class=\\"ms-1 d-inline-block\\">\\n                                    <input type=\\"hidden\\" name=\\"csrf_token\\" t-att-value=\\"request.csrf_token()\\"/>\\n                                    <button type=\\"submit\\" ro