ible=\\"1\\"/>\\n                            <field name=\\"videocall_source\\" invisible=\\"1\\"/>\\n                            <field name=\\"access_token\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                        </group>\\n                        <group>\\n                            <field name=\\"current_status\\" class=\\"o_calendar_form_status_selection_badge\\" string=\\"Going?\\" widget=\\"selection_badge\\" options=\\"{'horizontal': true, 'size': 'sm'}\\" required=\\"should_show_status\\" readonly=\\"not should_show_status\\" invisible=\\"not should_show_status\\"/>\\n                            <label for=\\"privacy\\" string=\\"Status\\"/>\\n                            <div class=\\"d-flex\\">\\n                                <field name=\\"show_as\\" class=\\"oe_inline me-2\\" readonly=\\"not user_can_edit\\" nolabel=\\"1\\"/>\\n                                <field name=\\"privacy\\" class=\\"oe_inline me-2\\" readonly=\\"not user_can_edit\\" nolabel=\\"1\\" placeholder=\\"User default\\" help=\\"Set whether you're available for other simultaneous events and the privacy of this event to others. Manage your default privacy in your user preferences.\\"/>\\n                            </div>\\n                            <field name=\\"should_show_status\\" invisible=\\"1\\"/>\\n                            <div class=\\"d-flex mb-2\\" colspan=\\"2\\">\\n                                <div>\\n                                    <span class=\\"fw-medium o_form_label\\">\\n                                        <field name=\\"attendees_count\\" class=\\"w-auto oe_inline\\" nolabel=\\"1\\"/><span> guests</span>\\n                                    </span>\\n                                    <div invisible=\\"not accepted_count and not tentative_count and not declined_count and not awaiting_count\\" class=\\"text-muted fw-normal\\">\\n                                        <span invisible=\\"not accepted_count\\" class=\\"me-1\\">\\n        