rrent_customer()"/>\n                    <t t-set="selected" t-value="address == selected_address"/>\n                    <t t-set="show_removal" t-value="can_be_edited and not selected and not is_user_address"/>\n                </t>\n            </t>\n        </div>\n    </t>\n\n    	f	t	2026-11-08 07:53:30.534247	2026-11-08 07:53:30.534247	f
