f=\\"show_removal\\">\\n                            <span class=\\"d-block border-start border-2 my-2\\"/>\\n                            <a class=\\"o_remove_address p-2 text-danger\\" role=\\"button\\" title=\\"Remove this address\\" aria-label=\\"Remove this address\\" t-att-data-partner-id=\\"contact.id\\">\\n                                <i class=\\"fa fa-fw fa-trash\\"/>\\n                            </a>\\n                        </t>\\n                    </div>\\n                </div>\\n            </div>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Address Card" t-name="portal.address_card">\n        <div name="address_card" t-attf-class="card o_address_card position-relative h-100 #{                 selected and 'bg-400 border border-primary'             }" t-att-data-address-type="address_type" t-att-data-partner-id="contact.id">\n            <div class="card-body d-flex flex-column flex-md-row justify-content-between gap-2">\n                <t t-out="contact" t-options="dict(widget='contact', fields=['name', 'address'], no_marker=True, no_tag_br=True)"/>\n                <t t-set="badge_classes" t-value="'badge text-bg-info'"/>\n                <div class="d-flex flex-row-reverse flex-md-column justify-content-between align-items-end">\n                    <span t-if="is_user_address" t-att-class=" badge_classes ">\n                        Main Address\n                    </span>\n                    <span t-elif="contact.type=='delivery'" t-att-class=" badge_classes ">\n                        Delivery Address\n                    </span>\n                    <span t-elif="contact.type=='invoice'" t-att-class=" badge_classes ">\n                        Billing Address\n                    </span>\n                    <div t-if="can_be_edited" class="d-flex gap-1 mt-auto ms-n2 ms-md-auto me-auto me-md-n2 mb-n2">\n                        <t t-set="address_update_url" t-value="address_update_url or (new_address_url + '&amp;partner_id=