key="x" invisible="won_status != 'lost'"/>\n                        <button name="198" string="Lost" type="action" data-hotkey="l" title="Mark as lost" invisible="won_status != 'pending' or not active"/>\n                        <field name="stage_id" widget="rotting_statusbar_duration" options="{'clickable': '1', 'fold_field': 'fold'}" domain="['|', ('team_ids', 'in', team_id), ('team_ids', '=', False)]" invisible="type == 'lead'" readonly="won_status == 'lost' or not active"/>\n                    </header>\n                    <sheet>\n                        <field name="won_status" invisible="1"/>\n                        <field name="active" invisible="1"/>\n                        <field name="company_id" invisible="1"/>\n                        <field name="is_rotting" invisible="1"/>\n                        <field name="rotting_days" invisible="1"/>\n                        <div class="oe_button_box" name="button_box">\n                            <button name="action_schedule_meeting" type="object" class="oe_stat_button" icon="fa-calendar" context="{'partner_id': partner_id}" invisible="not id or type == 'lead'">\n                                <div class="o_stat_info">\n                                    <span class="o_stat_text"><field name="meeting_display_label"/></span>\n                                    <field name="meeting_display_date" class="o_stat_value" invisible="not meeting_display_date"/>\n                                </div>\n                            </button>\n                            <button name="action_show_potential_duplicates" type="object" class="oe_stat_button" icon="fa-star" invisible="duplicate_lead_count &lt; 1">\n                                <div class="o_stat_info">\n                                    <field name="duplicate_lead_count" class="o_stat_value"/>\n                                    <span class="o_stat_text" invisible="duplicate_lead_count &lt; 2">Similar Leads</span>\n                               