f-id=\\"o_payment_token_{{token_sudo.id}}\\" name=\\"o_payment_radio\\" type=\\"radio\\" t-att-checked=\\"is_selected\\" t-att-disabled=\\"not allow_token_selection\\" t-att-class=\\"'form-check-input'                                             + (' d-none' if not allow_token_selection else '')\\" data-payment-option-type=\\"token\\" t-att-data-payment-option-id=\\"token_sudo.id\\" t-att-data-provider-code=\\"token_sudo.provider_id._get_code()\\" t-att-data-provider-id=\\"token_sudo.provider_id.id\\"/>\\n                        <div class=\\"d-flex align-items-center flex-wrap gap-2\\">\\n                            <!-- === Token label === -->\\n                            <label t-out=\\"token_sudo.payment_method_id.name\\" class=\\"o_payment_option_label text-break\\" t-attf-for=\\"o_payment_token_{{token_sudo.id}}\\"/>\\n                            <div class=\\"d-flex flex-nowrap gap-2\\">\\n                                <!-- === \\"Unpublished\\" icon === -->\\n                                <t t-if=\\"is_unpublished\\" t-call=\\"payment.form_icon\\">\\n                                    <t t-set=\\"icon_name\\" t-value=\\"'eye-slash'\\"/>\\n                                    <t t-set=\\"color_name\\" t-value=\\"'danger'\\"/>\\n                                    <t t-set=\\"title\\">Unpublished</t>\\n                                </t>\\n                                <!-- === \\"Test mode\\" icon === -->\\n                                <t t-if=\\"is_test\\" t-call=\\"payment.form_icon\\">\\n                                    <t t-set=\\"icon_name\\" t-value=\\"'exclamation-triangle'\\"/>\\n                                    <t t-set=\\"color_name\\" t-value=\\"'warning'\\"/>\\n                                    <t t-set=\\"title\\">Test mode</t>\\n                                </t>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </div>\\n                <!-- === Token name (p