783	16	\N	1	1	payment.state_header	\N	payment.state_header	qweb	payment/views/portal_templates.xml	primary	{"en_US": "<t t-name=\\"payment.state_header\\">\\n        <!-- Parameters description:\\n            - tx: The transaction whose status must be displayed.\\n            - is_processing: Whether the transaction is being processed.\\n        -->\\n        <t t-set=\\"waiting_heading\\">\\n            <p>Please wait...</p>\\n        </t>\\n        <t t-set=\\"tx_status_message\\" t-value=\\"tx.provider_id.sudo()._get_status_message(tx.state)\\"/>\\n        <t t-if=\\"tx.state == 'draft'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'warning'\\"/>\\n            <t t-if=\\"is_processing\\" t-set=\\"status_heading\\" t-value=\\"waiting_heading\\"/>\\n            <t t-set=\\"status_message\\">\\n                <p>Your payment has not been processed yet.</p>\\n            </t>\\n        </t>\\n        <t t-elif=\\"tx.state == 'pending'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'info'\\"/>\\n            <t t-if=\\"is_processing\\" t-set=\\"status_heading\\" t-value=\\"waiting_heading\\"/>\\n            <t t-if=\\"tx.operation == 'validation'\\" t-set=\\"status_message\\">\\n                <p>Saving your payment method.</p>\\n            </t>\\n            <t t-else=\\"\\" t-set=\\"status_message\\" t-value=\\"tx_status_message\\"/>\\n        </t>\\n        <t t-elif=\\"tx.state == 'authorized'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'success'\\"/>\\n            <t t-if=\\"is_processing\\" t-set=\\"status_heading\\" t-value=\\"waiting_heading\\"/>\\n            <t t-set=\\"status_message\\" t-value=\\"tx_status_message\\"/>\\n        </t>\\n        <t t-elif=\\"tx.state == 'done'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'success'\\"/>\\n            <t t-if=\\"not is_processing\\" t-set=\\"status_heading\\">\\n                <p>Thank you!</p>\\n            </t>\\n            <t t-if=\\"tx.operation == 'validation'\\" t-set=\\"status_message\\">\\n                <p>Your payment method has been saved.</p>\\n            </t>\\n            <t t-else=\\"\\" t-set=\\"status_message\\" t-value=\\"tx_status_message\\"/>\\n        </t>\\n        <t t-elif=\\"tx.state == 'cancel'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'danger'\\"/>\\n            <t t-if=\\"tx.operation == 'validation'\\" t-set=\\"status_message\\">\\n                <p>The saving of your payment method has been canceled.</p>\\n            </t>\\n            <t t-else=\\"\\" t-set=\\"status_message\\" t-value=\\"tx_status_message\\"/>\\n        </t>\\n        <t t-elif=\\"tx.state == 'error'\\">\\n            <t t-set=\\"alert_style\\" t-value=\\"'danger'\\"/>\\n            <t t-if=\\"tx.operation == 'validation'\\" t-set=\\"status_message\\">\\n                <p class=\\"mb-0\\">An error occurred while saving your payment method.</p>\\n            </t>\\n            <t t-else=\\"\\" t-set=\\"status_message\\">\\n                <p class=\\"mb-0\\">An error occurred during the processing of your payment.</p>\\n            </t>\\n        </t>\\n\\n        <t t-if=\\"not status_message\\" t-set=\\"status_message\\" t-value=\\"''\\"/>\\n        <t t-set=\\"o_payment_status_alert_class\\" t-value=\\"'alert alert-'+ alert_style +' d-flex gap-3'\\"/>\\n\\n        <div t-if=\\"status_heading or status_message or tx.state_message\\" name=\\"o_payment_status_alert\\" t-attf-class=\\"{{o_payment_status_alert_class}}\\">\\n            <t t-set=\\"alert_icon\\" t-value=\\"'fa-cog fa-spin' if is_processing and alert_style != 'danger'                         else 'fa-check' if alert_style == 'success'                         else 'fa-info-circle' if alert_style == 'info'                         else 'fa-exclamation-triangle'\\"/>\\n            <div id=\\"o_payment_status_icon\\">\\n                <i t-attf-class=\\"fa {{alert_icon}}\\"/>\\n            </div>\\n            <div id=\\"o_payment_status_message\\" class=\\"w-100\\">\\n                <h5 t-if=\\"status_heading\\" t-out=\\"status_heading\\" class=\\"alert-heading mb-0\\"/>\\n                <t t-if=\\"status_message\\" t-out=\\"status_message\\" class=\\"mb-0\\"/>\\n                <t t-if=\\"tx.state_message\\" t-out=\\"tx.state_message\\" class=\\"mb-0\\"/>\\n            </div>\\n            <a t-if=\\"is_processing\\" t-att-href=\\"tx.landing_route\\" class=\\"alert-link ms-auto text-nowrap\\">\\n                Skip <i class=\\"oi oi-arrow-right ms-1 small\\"/>\\n            </a>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="payment.state_header">\n        <!-- Parameters description:\n            - tx: The transaction whose status must be displayed.\n            - is_processing: Whether the transaction is being processed.\n        -->\n        <t t-set="waiting_heading">\n            <p>Please wait...</p>\n        </t>\n        <t t-set="tx_status_message" t-value="tx.provider_id.sudo()._get_status_message(tx.state)"/>\n        <t t-if="tx.state == 'draft'">\n            <t t-set="alert_style" t-value="'warning'"/>\n            <t t-if="is_processing" t-set="status_heading" t-value="waiting_heading"/>\n            <t t-set="status_message">\n                <p>Your payment has not been processed yet.</p>\n            </t>\n        </t>\n        <t t-elif="tx.state == 'pending'">\n            <t t-set="alert_style" t-value="'info'"/>\n            <t t-if="is_processing" t-set="status_heading" t-value="waiting_heading"/>\n            <t t-if="tx.operation == 'validation'" t-set="status_message">\n                <p>Saving your payment method.</p>\n            </t>\n            <t t-else="" t-set="status_message" t-value="tx_status_message"/>\n        </t>\n        <t t-elif="tx.state == 'authorized'">\n            <t t-set="alert_style" t-value="'success'"/>\n            <t t-if="is_processing" t-set="status_heading" t-value="waiting_heading"/>\n            <t t-set="status_message" t-value="tx_status_message"/>\n        </t>\n        <t t-elif="tx.state == 'done'">\n            <t t-set="alert_style" t-value="'success'"/>\n            <t t-if="not is_processing" t-set="status_heading">\n                <p>Thank you!</p>\n            </t>\n            <t t-if="tx.operation == 'validation'" t-set="status_message">\n                <p>Your payment method has been saved.</p>\n            </t>\n            <t t-else="" t-set="status_message" t-value="tx_status_message"/>\n        </t>\n        <t t-elif="tx.state == 'cancel'">\n            <t t-set="alert_style" t-value="'danger'"/>\n            <t t-if="tx.operation == 'validation'" t-set="status_message">\n                <p>The saving of your payment method has been canceled.</p>\n            </t>\n            <t t-else="" t-set="status_message" t-value="tx_status_message"/>\n        </t>\n        <t t-elif="tx.state == 'error'">\n            <t t-set="alert_style" t-value="'danger'"/>\n            <t t-if="tx.operation == 'validation'" t-set="status_message">\n                <p class="mb-0">An error occurred while saving your payment method.</p>\n            </t>\n            <t t-else="" t-set="status_message">\n                <p class="mb-0">An error occurred during the processing of your payment.</p>\n            </t>\n        </t>\n\n        <t t-if="not status_message" t-set="status_message" t-value="''"/>\n        <t t-set="o_payment_status_alert_class" t-value="'alert alert-'+ alert_style +' d-flex gap-3'"/>\n\n        <div t-if="status_heading or status_message or tx.state_message" name="o_payment_status_alert" t-attf-class="{{o_payment_status_alert_class}}">\n            <t t-set="alert_icon" t-value="'fa-cog fa-spin' if is_processing and alert_style != 'danger'                         else 'fa-check' if alert_style == 'success'                         else 'fa-info-circle' if alert_style == 'info'                         else 'fa-exclamation-triangle'"/>\n            <div id="o_payment_status_icon">\n                <i t-attf-class="fa {{alert_icon}}"/>\n            </div>\n            <div id="o_payment_status_message" class="w-100">\n                <h5 t-if="status_heading" t-out="status_heading" class="alert-heading mb-0"/>\n                <t t-if="status_message" t-out="status_message" class="mb-0"/>\n                <t t-if="tx.state_message" t-out="tx.state_message" class="mb-0"/>\n            </div>\n            <a t-if="is_processing" t-att-href="tx.landing_route" class="alert-link ms-auto text-nowrap">\n                Skip <i class="oi oi-arrow-right ms-1 small"/>\n            </a>\n        </div>\n    </t>\n\n    	f	t	2026-11-08 08:02:03.00756	2026-11-08 08:02:03.00756	f
