926	16	\N	1	1	document_tax_totals_template	\N	account.document_tax_totals_template	qweb	account/views/report_invoice.xml	primary	{"en_US": "<t t-name=\\"account.document_tax_totals_template\\">\\n            <!--\\n                Generic template to display tax totals in pdf reports.\\n                Used by invoices, SO and PO.\\n\\n                ARGUMENTS:\\n                - currency: The res.currency to use.\\n                - tax_totals: dict in the form generated by account.move's _get_tax_totals.\\n            -->\\n            <t t-set=\\"same_tax_base\\" t-value=\\"tax_totals['same_tax_base']\\"/>\\n            <t t-foreach=\\"tax_totals['subtotals']\\" t-as=\\"subtotal\\">\\n                <tr t-if=\\"subtotal['tax_groups']\\" class=\\"o_subtotal\\">\\n                    <td>\\n                        <span t-out=\\"subtotal['name']\\">Untaxed Amount</span>\\n                    </td>\\n                    <td class=\\"text-end\\">\\n                        <span t-att-class=\\"oe_subtotal_footer_separator\\" t-out=\\"subtotal['base_amount_currency']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}\\">27.00</span>\\n                    </td>\\n                </tr>\\n\\n                <t t-foreach=\\"subtotal['tax_groups']\\" t-as=\\"tax_group\\">\\n                    <tr class=\\"o_taxes\\">\\n                        <t t-if=\\"same_tax_base or tax_group['display_base_amount_currency'] is False\\">\\n                            <td style=\\"max-width: 200px;\\">\\n                                <span t-out=\\"tax_group['group_name']\\">Tax 15%</span>\\n                            </td>\\n                            <td class=\\"text-end o_price_total\\">\\n                                <span class=\\"text-nowrap\\" t-out=\\"tax_group['tax_amount_currency']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}\\">1.05</span>\\n                            </td>\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            <td>\\n                                <span t-out=\\"tax_group['group_name']\\">Tax 15%</span>\\n                                <span> on </span>\\n                                <span class=\\"text-nowrap\\" t-out=\\"tax_group['display_base_amount_currency']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}\\">27.00</span>\\n                            </td>\\n                            <td class=\\"text-end o_price_total\\">\\n                                <span class=\\"text-nowrap\\" t-out=\\"tax_group['tax_amount_currency']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}\\">4.05</span>\\n                            </td>\\n                        </t>\\n                    </tr>\\n                </t>\\n            </t>\\n\\n            <tr t-if=\\"'cash_rounding_base_amount_currency' in tax_totals\\">\\n                <td>Rounding</td>\\n                <td class=\\"text-end\\">\\n                    <span t-out=\\"tax_totals['cash_rounding_base_amount_currency']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}\\">0</span>\\n                </td>\\n            </tr>\\n\\n            <!--Total amount with all taxes-->\\n            <tr class=\\"o_total\\">\\n                <td><strong>Total</strong></td>\\n                <td class=\\"text-end\\">\\n                    <strong t-out=\\"tax_totals['total_amount_currency']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}\\">31.05</strong>\\n                </td>\\n            </tr>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="account.document_tax_totals_template">\n            <!--\n                Generic template to display tax totals in pdf reports.\n                Used by invoices, SO and PO.\n\n                ARGUMENTS:\n                - currency: The res.currency to use.\n                - tax_totals: dict in the form generated by account.move's _get_tax_totals.\n            -->\n            <t t-set="same_tax_base" t-value="tax_totals['same_tax_base']"/>\n            <t t-foreach="tax_totals['subtotals']" t-as="subtotal">\n                <tr t-if="subtotal['tax_groups']" class="o_subtotal">\n                    <td>\n                        <span t-out="subtotal['name']">Untaxed Amount</span>\n                    </td>\n                    <td class="text-end">\n                        <span t-att-class="oe_subtotal_footer_separator" t-out="subtotal['base_amount_currency']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}">27.00</span>\n                    </td>\n                </tr>\n\n                <t t-foreach="subtotal['tax_groups']" t-as="tax_group">\n                    <tr class="o_taxes">\n                        <t t-if="same_tax_base or tax_group['display_base_amount_currency'] is False">\n                            <td style="max-width: 200px;">\n                                <span t-out="tax_group['group_name']">Tax 15%</span>\n                            </td>\n                            <td class="text-end o_price_total">\n                                <span class="text-nowrap" t-out="tax_group['tax_amount_currency']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}">1.05</span>\n                            </td>\n                        </t>\n                        <t t-else="">\n                            <td>\n                                <span t-out="tax_group['group_name']">Tax 15%</span>\n                                <span> on </span>\n                                <span class="text-nowrap" t-out="tax_group['display_base_amount_currency']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}">27.00</span>\n                            </td>\n                            <td class="text-end o_price_total">\n                                <span class="text-nowrap" t-out="tax_group['tax_amount_currency']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}">4.05</span>\n                            </td>\n                        </t>\n                    </tr>\n                </t>\n            </t>\n\n            <tr t-if="'cash_rounding_base_amount_currency' in tax_totals">\n                <td>Rounding</td>\n                <td class="text-end">\n                    <span t-out="tax_totals['cash_rounding_base_amount_currency']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}">0</span>\n                </td>\n            </tr>\n\n            <!--Total amount with all taxes-->\n            <tr class="o_total">\n                <td><strong>Total</strong></td>\n                <td class="text-end">\n                    <strong t-out="tax_totals['total_amount_currency']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: currency}">31.05</strong>\n                </td>\n            </tr>\n        </t>\n\n         	f	t	2026-11-08 08:02:07.347134	2026-11-08 08:02:07.347134	f
