 line discounts:\\" title=\\"If empty, the discount will be discounted directly on the income/expense account. If set, discount on invoices will be realized in separate accounts.\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_discount_expense_allocation_id\\" class=\\"col-lg-5 o_light_label\\" string=\\"Customer Invoices\\"/>\\n                                            <field name=\\"account_discount_expense_allocation_id\\" placeholder=\\"Same Account as product\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\" id=\\"account_discount_income_allocation\\">\\n                                            <label for=\\"account_discount_income_allocation_id\\" class=\\"col-lg-5 o_light_label\\" string=\\"Vendor Bills\\"/>\\n                                            <field name=\\"account_discount_income_allocation_id\\" placeholder=\\"Same Account as product\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting string=\\"Early payment discounts:\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_early_pay_discount_gain_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_early_pay_discount_gain_account_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"account_journal_early_pay_discount_loss_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"account_journal_early_pay_discount_loss_account_id\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                                <setting id=\\"product_accounts\\" string=\\"Product Accounts:\\">\\n                                    <div class=\\"content-group\\">\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"income_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"income_account_id\\"/>\\n                                        </div>\\n                                        <div class=\\"row mt8\\">\\n                                            <label for=\\"expense_account_id\\" class=\\"col-lg-5 o_light_label\\"/>\\n                                            <field name=\\"expense_account_id\\"/>\\n                                        </div>\\n                                    </div>\\n                                </setting>\\n                            </block>\\n                        </t>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Bank &amp; Cash\\" id=\\"bank_cash\\">\\n                                <setting title=\\"Once installed, set 'Bank Feeds' to 'File Import' in bank account settings.This adds a button to import from the Accounting dashboard.\\" string=\\"QIF Import\\" help=\\"Import your bank statements in QIF\\">\\n                                    <field name=\\"module_account_bank_statement_import_qif\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                            </block>\\n                        </t>\\n\\n                        <t groups=\\"account.group_account_user\\">\\n                            <block title=\\"Fiscal Periods\\" id=\\"accounting_reports\\">\\n                                <setting id=\\"fiscalyear\\" invisible=\\"1\\" groups=\\"account.group_account_user\\"/>\\n                                <setting id=\\"dynamic_report\\" groups=\\"account.group_account_user\\" help=\\"Navigate easily through reports and see what is behind the numbers\\">\\n                                    <field name=\\"module_account_reports\\" widget=\\"upgrade_boolean\\"/>\\n                                </setting>\\n                            </block>\\n                        </t>\\n                        <block title=\\"Analytics\\" id=\\"analytic\\" groups=\\"account.group_account_user\\">\\n                            <setting id=\\"track_costs_revenues\\" title=\\"Allows you to use the analytic accounting.\\" groups=\\"account.group_account_user\\" help=\\"Track costs &amp; revenues by project, department, etc\\" documentation=\\"/applications/finance/accounting/others/analytic_accounting.html\\">\\n                                <field name=\\"group_analytic_accounting\\"/>\\n                            </setting>\\n                            <setting id=\\"account_budget\\" title=\\"This allows accountants to manage analytic and crossovered budgets. Once the master budgets and the budgets are defined, the project managers can set the planned amount on each analytic account.\\" groups=\\"account.group_account_user\\" help=\\"Use budgets to compare actual with expected revenues and costs\\" documentation=\\"/applications/finance/accounting/others/adviser/budget.html\\">\\n                                <field name=\\"module_account_budget\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"monitor_product_margins\\" string=\\"Margin Analysis\\" help=\\"Monitor your product margins from invoices\\" groups=\\"account.group_account_user\\">\\n                                <field name=\\"module_product_margin\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Reporting\\" id=\\"account_reports_settings\\" groups=\\"account.group_account_user\\" invisible=\\"not module_account_reports\\">\\n                            <setting string=\\"Restrictive Audit Trail\\" company_dependent=\\"1\\" invisible=\\"force_restrictive_audit_trail\\" help=\\"Log changes to posted journal entries immutably\\">\\n                                <field name=\\"restrictive_audit_trail\\"/>\\n                            </setting>\\n                        </block>\\n                        <field name=\\"is_account_peppol_eligible\\" invisible=\\"1\\"/>\\n                        <block title=\\"Storno Accounting\\" id=\\"storno\\" groups=\\"account.group_account_user\\" invisible=\\"not display_account_storno\\">\\n                            <setting id=\\"enable_storno_accounting\\" company_dependent=\\"1\\" help=\\"Use negative numbers to reverse original entries\\">\\n                                <field name=\\"account_storno\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Accounting Firms mode\\" id=\\"quick_edit_mode\\">\\n                            <div class=\\"text-muted\\">\\n                                <p style=\\"margin-bottom: 0\\">Accounting firm mode will change invoice/bill encoding:</p>\\n                                <p style=\\"margin-bottom: 0\\"> - The document's sequence becomes editable on all documents.</p>\\n                                <p style=\\"margin-bottom: 0\\"> - A new field « Total (tax inc.) » to speed up and control the encoding by automating line creation with the right account &amp; tax.</p>\\n                            </div>\\n                            <setting company_dependent=\\"1\\">\\n                                <field name=\\"quick_edit_mode\\" placeholder=\\"Disabled\\"/>\\n                            </setting>\\n                        </block>\\n                    </app>\\n                </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                    <field name="country_code" invisible="1" groups="account.group_account_manager"/>\n                    <app data-string="Invoicing" string="Invoicing" name="account" groups="account.group_account_manager">\n                        <field name="has_chart_of_accounts" invisible="1"/>\n                        <field name="has_accounting_entries" invisible="1"/>\n                        <block title="Fiscal Localization" name="fiscal_localization_setting_container" invisible="not is_root_company">\n                            <setting string="Fiscal Localization" company_dependent="1" help="Taxes, fiscal positions, chart of accounts &amp; legal statements for your country" documentation="/applications/finance/fiscal_localizations.html">\n                                <div class="content-group">\n                                    <div class="mt16">\n                                        <div>\n                                            <label for="chart_template" string="Package" class="col-2 o_light_label"/>\n                                            <field name="chart_template" readonly="has_accounting_entries" required="chart_template"/>\n                                        </div>\n                                        <div class="mt16">\n                                            <button name="reload_template" type="object" string="Reload" class="btn-secondary ps-2 w-100" icon="fa-refresh" title="Reload accounting data (taxes, accounts, ...) if you notice inconsistencies. This action is irreversible." invisible="not has_accounting_entries or not chart_template"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </setting>\n                        </block>\n                        <block title="Electronic Invoicing" id="peppol" invisible="not is_account_peppol_eligible">\n                            <div id="account_peppol_install" class="col-12 col-lg-12 o_setting_box">\n                                <div class="o_setting_left_pane">\n                                    <field name="module_account_peppol" readonly="False"/>\n                                </div>\n                                <div class="o_setting_right_pane">\n                                    <label for="module_account_peppol" string="Enable PEPPOL"/>\n                                    <div class="text-muted">\n                                        Allow sending and receiving invoices through the PEPPOL network\n                                    </div>\n                                </div>\n                            </div>\n                        </block>\n                        <block title="Taxes" name="default_taxes_setting_container">\n                            <setting id="default_taxes" string="Default Taxes" company_dependent="1" help="Default taxes applied when creating new products." documentation="/applications/finance/accounting/taxation/taxes/default_taxes.html">\n                                <div class="content-group">\n                                    <div class="row mt16">\n                                        <label string="Sales Tax" for="sale_tax_id" class="col-lg-3 o_light_label"/>\n                                        <field name="sale_tax_id" domain="[('type_tax_use', 'in', ('sale', 'all'))]"/>\n                                    </div>\n                                    <div class="row">\n                                        <label string="Purchase Tax" for="purchase_tax_id" class="col-lg-3 o_light_label"/>\n                                        <field name="purchase_tax_id" domain="[('type_tax_use', 'in', ('purchase', 'all'))]"/>\n                                    </div>\n                                    <div class="row">\n                                        <div class="col-lg-3">\n                                            <label string="Prices" for="account_price_include" class="o_light_label"/>\n                                            <div class="fa fa-question-circle" title="This setting locks once a journal entry is created."/>\n                                        </div>\n                                        <field name="account_price_include" readonly="has_accounting_entries"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="rounding_method" company_dependent="1" string="Rounding Method" help="How total tax amount is computed in orders and invoices" title="A rounding per line is advised if your prices are tax-included. That way, the sum of line subtotals equals the total with taxes.">\n                                <field name="tax_calculation_rounding_method" class="o_light_label mt16" widget="radio"/>\n                            </setting>\n                            <setting id="eu_service" title="If you sell goods and services to customers in a                                 foreign EU country, you must charge VAT based on the delivery address.                                 This rule applies regardless of where you are located." string="EU Intra-community Distance Selling" documentation="/applications/finance/accounting/taxation/taxes/eu_distance_selling.html" help="Apply VAT of the EU country to which goods and services are delivered." invisible="not('EU' in company_country_group_codes or company_country_code in ('CH', 'UK'))">\n                                <button type="object" name="action_eu_oss_tax_mapping" icon="fa-refresh" string="OSS Tax mapping" class="btn-link"/>\n                            </setting>\n                            <setting id="tax_exigibility" company_dependent="1" help="Allow to configure taxes using cash basis" title="Select this if the taxes should use cash basis, which will create an entry for such taxes on a given account during reconciliation." documentation="/applications/finance/accounting/taxation/taxes/cash_basis_taxes.html">\n                                <field name="tax_exigibility"/>\n                                <div class="content-group" invisible="not tax_exigibility" groups="account.group_account_user">\n                                    <div class="row mt16">\n                                        <label for="tax_cash_basis_journal_id" class="col-lg-3 o_light_label"/>\n                                        <field name="tax_cash_basis_journal_id"/>\n                                    </div>\n                                    <div class="row mt16">\n                                        <label for="account_cash_basis_base_account_id" class="col-lg-3 o_light_label"/>\n                                        <field name="account_cash_basis_base_account_id"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="tax_fiscal_country_234" string="Fiscal Country" company_dependent="1" help="Domestic country of your accounting">\n                                <field name="account_fiscal_country_id" options="{'no_create': True, 'no_open': True}"/>\n                            </setting>\n                        </block>\n                        <block title="Currencies" name="main_currency_setting_container">\n                            <setting id="main_currency" string="Main Currency" company_dependent="1" help="Main currency of your company" documentation="/applications/finance/accounting/others/multi_currency.html">\n                                <div class="content-group">\n                                    <div class="row mt16">\n                                        <label for="currency_id" class="col-lg-3 o_light_label"/>\n                                        <field name="currency_id" options="{'no_create_edit': True, 'no_open': True}" context="{'active_test': False}"/>\n                                        <field name="group_multi_currency" invisible="1"/>\n                                    </div>\n                                    <div class="mt8">\n                                        <button type="action" name="66" string="Currencies" class="btn-link" icon="oi-arrow-right"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="update_exchange_rates" invisible="not group_multi_currency" help="Update exchange rates automatically" documentation="/applications/finance/accounting/others/multi_currency.html">\n                                <field name="module_currency_rate_live" widget="upgrade_boolean"/>\n                            </setting>\n                        </block>\n                        <block title="Customer Invoices" id="invoicing_settings">\n                            <setting id="send_invoices_followups" help="Send invoices and payment follow-ups by post" documentation="/applications/finance/accounting/receivables/customer_invoices/snailmail.html">\n                                <field name="module_snailmail_account"/>\n                            </setting>\n                            <setting id="invoice_delivery_addresses" documentation="/applications/sales/sales/send_quotations/different_addresses.html" help="Select specific invoice and delivery addresses">\n                                <field name="group_sale_delivery_address"/>\n                            </setting>\n                            <setting id="smallest_coinage_currency" help="Define the smallest coinage of the currency used to pay by cash" documentation="/applications/finance/accounting/receivables/customer_invoices/cash_rounding.html">\n                                <field name="group_cash_rounding"/>\n                                <div class="mt8">\n                                    <button name="339" icon="oi-arrow-right" type="action" string="Cash Roundings" class="btn-link" invisible="not group_cash_rounding"/>\n                                </div>\n                            </setting>\n                            <setting id="intrastat_statistics" help="Collect information and produce statistics on the trade in goods in Europe with intrastat" documentation="/applications/finance/accounting/reporting/declarations/intrastat.html" invisible="'INTRASTAT' not in company_country_group_codes">\n                                <field name="module_account_intrastat" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="default_incoterm" string="Default Incoterm" help="Default Incoterm of your company">\n                                <field name="incoterm_id"/>\n                            </setting>\n                            <setting id="show_sale_receipts" help="Activate to create sale receipt">\n                                <field name="show_sale_receipts"/>\n                            </setting>\n                            <setting id="use_invoice_terms" company_dependent="1" help="Add your terms &amp; conditions at the bottom of invoices/orders/quotations">\n                                <field name="use_invoice_terms"/>\n                                <div class="content-group" invisible="not use_invoice_terms">\n                                    <div class="mt16">\n                                        <field name="terms_type" class="o_light_label" widget="radio"/>\n                                        <div>\n                                            <field name="invoice_terms" invisible="terms_type == 'html'" class="oe_account_terms mt-5 w-100" placeholder="Insert your terms &amp; conditions here..."/>\n                                        </div>\n                                        <div class="mt8" invisible="terms_type != 'html'">\n                                            <button name="action_update_terms" icon="oi-arrow-right" type="object" string="Update Terms" class="btn-link"/>\n                                        </div>\n                                        <field name="preview_ready" invisible="1"/>\n                                        <div class="mt4 ms-1" invisible="not preview_ready">\n                                            <a class="btn-link" href="/terms" role="button">\n                                                <i class="oi oi-arrow-right"/>\n                                                Preview\n                                            </a>\n                                        </div>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting company_dependent="1" help="Trigger alerts when creating Invoices and Sales Orders for Partners with a Total Receivable amount exceeding a limit.                                      Set a value greater than 0.0 to activate a credit limit check">\n                                <field name="account_use_credit_limit"/>\n                                <div class="content-group mt-2" invisible="not account_use_credit_limit">\n                                    <div class="row">\n                                        <label for="account_default_credit_limit" class="col-lg-4 o_light_label"/>\n                                        <field name="account_default_credit_limit"/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="total_amount_words" company_dependent="1" help="Display the total amount of an invoice in letters">\n                                <field name="display_invoice_amount_total_words"/>\n                            </setting>\n                            <setting id="display_invoice_tax_company_currency" company_dependent="1" help="Taxes are also displayed in local currency on invoices">\n                                <field name="display_invoice_tax_company_currency"/>\n                            </setting>\n                        </block>\n                        <block title="Units &amp; Packagings">\n                            <setting id="account_uom" help="Sell and purchase products in different units of measure or packagings">\n                                <field name="group_uom"/>\n                                <div class="content-group" invisible="not group_uom">\n                                    <button name="233" icon="oi-arrow-right" type="action" string="Units &amp; Packagings" class="btn-link"/>\n                                </div>\n                            </setting>\n                        </block>\n                        <block title="Customer Payments" id="pay_invoice_online_setting_container">\n                            <setting help="Let your customers pay their invoices online" documentation="/applications/finance/accounting/receivables/customer_payments/online_payment.html">\n                                <field name="module_account_payment"/>\n                                <div class="mt-3 d-flex" invisible="not module_account_payment">\n                                    <field name="link_qr_code" string="Add QR-code link on PDF"/>\n                                    <div>\n                                        <label for="link_qr_code"/><br/>\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="account_batch_payment" string="Batch Payments" help="Group payments into a single batch to ease the reconciliation process" documentation="/applications/finance/accounting/receivables/customer_payments/batch.html">\n                                <field name="module_account_batch_payment" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="collect_customer_payment" title="If you check this box, you will be able to collect payments using SEPA Direct Debit mandates." string="SEPA Direct Debit (SDD)" company_dependent="1" help="Collect customer payments in one-click using Euro SEPA Service" documentation="/applications/finance/accounting/receivables/customer_payments/batch_sdd.html" invisible="'SEPA' not in company_country_group_codes">\n                                <field name="module_account_sepa_direct_debit" class="oe_inline" widget="upgrade_boolean"/>\n                                <div class="content-group" invisible="not module_account_sepa_direct_debit">\n                                    <div class="text-warning mt16 mb4">\n                                        Save this page and come back here to set up the feature.\n                                    </div>\n                                </div>\n                            </setting>\n                            <setting id="qr_code_invoices" title="Add a QR-code to your invoices so that your customers can pay instantly with their mobile banking application." string="QR Codes" company_dependent="1" help="Add a payment QR-code to your invoices" documentation="/applications/finance/accounting/receivables/customer_invoices/epc_qr_code.html">\n                                <field name="qr_code" class="oe_inline"/>\n                            </setting>\n                        </block>\n                        <block title="Vendor Bills" id="account_vendor_bills">\n                            <setting id="autopost_bills" help="Propose to validate bills automatically when AI accuracy is right 3 times in a row for a vendor.">\n                                <field name="autopost_bills"/>\n                            </setting>\n                        </block>\n                        <block title="Vendor Payments" id="print_vendor_checks_setting_container">\n                            <setting id="print_checks" groups="account.group_account_user" string="Checks" company_dependent="1" help="Print checks to pay your vendors" documentation="/applications/finance/accounting/payables/pay/check.html">\n                                <field name="module_account_check_printing"/>\n                            </setting>\n                            <setting id="sepa_payments" title="If you check this box, you will be able to register your payment using SEPA / ISO20022." company_dependent="1" help="Pay your bills in one-click using Euro SEPA Service / ISO20022" documentation="/applications/finance/accounting/payables/pay/sepa.html">\n                                <field name="module_account_iso20022" widget="upgrade_boolean"/>\n                            </setting>\n                        </block>\n\n                        <block title="Digitization" id="account_digitalization">\n                            <setting id="account_ocr_settings" help="Digitize your PDF or scanned documents with OCR and Artificial Intelligence" documentation="/applications/finance/accounting/payables/supplier_bills/invoice_digitization.html">\n                                <field name="module_account_extract" widget="upgrade_boolean"/>\n                                <div id="msg_invoice_extract" class="content-group" invisible="not module_account_extract">\n                                    <div class="text-warning mt16 mb4">\n                                        Save this page and come back here to set up the feature.\n                                    </div>\n                                </div>\n                            </setting>\n                        </block>\n\n                     