955	16	\N	1	1	My Invoices and Payments	\N	account.portal_my_invoices	qweb	account/views/account_portal_templates.xml	primary	{"en_US": "<t name=\\"My Invoices and Payments\\" t-name=\\"account.portal_my_invoices\\">\\n      <t t-call=\\"portal.portal_layout\\">\\n        <t t-set=\\"breadcrumbs_searchbar\\" t-value=\\"True\\"/>\\n\\n        <t t-call=\\"portal.portal_searchbar\\">\\n            <t t-set=\\"title\\">Invoices</t>\\n        </t>\\n        <t t-if=\\"not invoices\\">\\n            <p class=\\"alert alert-warning\\">There are currently no invoices and payments for your account.</p>\\n        </t>\\n        <t t-if=\\"invoices\\" t-call=\\"portal.portal_table\\">\\n            <thead>\\n                <tr class=\\"active\\">\\n                    <th name=\\"invoice_number\\">Invoice #</th>\\n                    <th name=\\"invoice_date\\">Invoice Date</th>\\n                    <th name=\\"due_date\\" class=\\"d-none d-md-table-cell\\">Due Date</th>\\n                    <th name=\\"amount_due\\" class=\\"text-end pe-3\\">Amount Due</th>\\n                    <th name=\\"status\\">Status</th>\\n                </tr>\\n            </thead>\\n            <tbody>\\n                <t t-foreach=\\"invoices\\" t-as=\\"invoice_data\\">\\n                    <t t-set=\\"invoice\\" t-value=\\"invoice_data['invoice']\\"/>\\n                    <tr>\\n                        <td>\\n                            <a t-att-href=\\"invoice.get_portal_url()\\" t-att-title=\\"invoice.name\\">\\n                                <t t-out=\\"invoice.name\\" t-if=\\"invoice.name != '/'\\"/>\\n                                <em t-else=\\"\\">Draft Invoice</em>\\n                            </a>\\n                        </td>\\n                        <td><span t-field=\\"invoice.invoice_date\\"/></td>\\n                        <td class=\\"d-none d-md-table-cell\\" t-att-class=\\"'d-none d-md-table-cell text-danger' if invoice.invoice_date_due and invoice.invoice_date_due &lt; datetime.date.today() and invoice.payment_state in ['not_paid', 'partial'] else 'd-none d-md-table-cell'\\">\\n                            <span t-field=\\"invoice.invoice_date_due\\"/>\\n                        </td>\\n                        <td name=\\"invoice_amount\\" class=\\"text-end pe-3\\"><span t-out=\\"-invoice.amount_residual if invoice.move_type == 'out_refund' else invoice.amount_residual\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}\\"/></td>\\n                        <td name=\\"invoice_status\\">\\n                            <t t-if=\\"invoice.state == 'posted'\\" name=\\"invoice_status_posted\\">\\n                                <span t-if=\\"invoice.currency_id.is_zero(invoice.amount_residual)\\" class=\\"badge rounded-pill text-bg-success\\">\\n                                    <i class=\\"fa fa-fw fa-check\\" aria-label=\\"Paid\\" title=\\"Paid\\" role=\\"img\\"/>\\n                                    <span class=\\"d-none d-md-inline\\"> Paid</span>\\n                                </span>\\n                                <span t-elif=\\"invoice.payment_state == 'in_payment' and not invoice.currency_id.is_zero(invoice.amount_residual)\\" class=\\"badge rounded-pill text-bg-info\\">\\n                                    <i class=\\"fa fa-fw fa-check\\" aria-label=\\"processing_payment\\" title=\\"Processing Payment\\" role=\\"img\\"/>\\n                                    <span class=\\"d-none d-md-inline\\"> Processing Payment</span>\\n                                </span>\\n                                <span t-elif=\\"invoice.payment_state == 'reversed'\\" class=\\"badge rounded-pill text-bg-success\\">\\n                                    <i class=\\"fa fa-fw fa-check\\" aria-label=\\"Reversed\\" title=\\"Reversed\\" role=\\"img\\"/>\\n                                    <span class=\\"d-none d-md-inline\\"> Reversed</span>\\n                                </span>\\n                                <span t-else=\\"\\" class=\\"badge rounded-pill text-bg-info\\" name=\\"invoice_status_waiting_for_payment\\">\\n                                    <i class=\\"fa fa-fw fa-clock-o\\" aria-label=\\"Opened\\" title=\\"Opened\\" role=\\"img\\"/>\\n                                    <span class=\\"d-none d-md-inline\\"> Waiting for Payment</span>\\n                                </span>\\n                            </t>\\n                            <t t-elif=\\"invoice.state == 'cancel'\\">\\n                                <span class=\\"badge rounded-pill text-bg-warning\\">\\n                                    <i class=\\"fa fa-fw fa-remove\\" aria-label=\\"Cancelled\\" title=\\"Cancelled\\" role=\\"img\\"/>\\n                                    <span class=\\"d-none d-md-inline\\"> Cancelled</span>\\n                                </span>\\n                            </t>\\n                        </td>\\n                    </tr>\\n                </t>\\n            </tbody>\\n        </t>\\n      </t>\\n    </t>"}	<?xml version="1.0"?>\n<t name="My Invoices and Payments" t-name="account.portal_my_invoices">\n      <t t-call="portal.portal_layout">\n        <t t-set="breadcrumbs_searchbar" t-value="True"/>\n\n        <t t-call="portal.portal_searchbar">\n            <t t-set="title">Invoices</t>\n        </t>\n        <t t-if="not invoices">\n            <p class="alert alert-warning">There are currently no invoices and payments for your account.</p>\n        </t>\n        <t t-if="invoices" t-call="portal.portal_table">\n            <thead>\n                <tr class="active">\n                    <th name="invoice_number">Invoice #</th>\n                    <th name="invoice_date">Invoice Date</th>\n                    <th name="due_date" class="d-none d-md-table-cell">Due Date</th>\n                    <th name="amount_due" class="text-end pe-3">Amount Due</th>\n                    <th name="status">Status</th>\n                </tr>\n            </thead>\n            <tbody>\n                <t t-foreach="invoices" t-as="invoice_data">\n                    <t t-set="invoice" t-value="invoice_data['invoice']"/>\n                    <tr>\n                        <td>\n                            <a t-att-href="invoice.get_portal_url()" t-att-title="invoice.name">\n                                <t t-out="invoice.name" t-if="invoice.name != '/'"/>\n                                <em t-else="">Draft Invoice</em>\n                            </a>\n                        </td>\n                        <td><span t-field="invoice.invoice_date"/></td>\n                        <td class="d-none d-md-table-cell" t-att-class="'d-none d-md-table-cell text-danger' if invoice.invoice_date_due and invoice.invoice_date_due &lt; datetime.date.today() and invoice.payment_state in ['not_paid', 'partial'] else 'd-none d-md-table-cell'">\n                            <span t-field="invoice.invoice_date_due"/>\n                        </td>\n                        <td name="invoice_amount" class="text-end pe-3"><span t-out="-invoice.amount_residual if invoice.move_type == 'out_refund' else invoice.amount_residual" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/></td>\n                        <td name="invoice_status">\n                            <t t-if="invoice.state == 'posted'" name="invoice_status_posted">\n                                <span t-if="invoice.currency_id.is_zero(invoice.amount_residual)" class="badge rounded-pill text-bg-success">\n                                    <i class="fa fa-fw fa-check" aria-label="Paid" title="Paid" role="img"/>\n                                    <span class="d-none d-md-inline"> Paid</span>\n                                </span>\n                                <span t-elif="invoice.payment_state == 'in_payment' and not invoice.currency_id.is_zero(invoice.amount_residual)" class="badge rounded-pill text-bg-info">\n                                    <i class="fa fa-fw fa-check" aria-label="processing_payment" title="Processing Payment" role="img"/>\n                                    <span class="d-none d-md-inline"> Processing Payment</span>\n                                </span>\n                                <span t-elif="invoice.payment_state == 'reversed'" class="badge rounded-pill text-bg-success">\n                                    <i class="fa fa-fw fa-check" aria-label="Reversed" title="Reversed" role="img"/>\n                                    <span class="d-none d-md-inline"> Reversed</span>\n                                </span>\n                                <span t-else="" class="badge rounded-pill text-bg-info" name="invoice_status_waiting_for_payment">\n                                    <i class="fa fa-fw fa-clock-o" aria-label="Opened" title="Opened" role="img"/>\n                                    <span class="d-none d-md-inline"> Waiting for Payment</span>\n                                </span>\n                            </t>\n                            <t t-elif="invoice.state == 'cancel'">\n                                <span class="badge rounded-pill text-bg-warning">\n                                    <i class="fa fa-fw fa-remove" aria-label="Cancelled" title="Cancelled" role="img"/>\n                                    <span class="d-none d-md-inline"> Cancelled</span>\n                                </span>\n                            </t>\n                        </td>\n                    </tr>\n                </t>\n            </tbody>\n        </t>\n      </t>\n    </t>\n\n    	f	t	2026-11-08 08:02:07.347134	2026-11-08 08:02:07.347134	f
