not parent.allow_milestones\\" invisible=\\"not allow_milestones\\"/>\\n                                    <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"partner_id\\" readonly=\\"not current_user_same_company_partner\\" options=\\"{'no_open': True, 'no_create': True, 'no_edit': True}\\" optional=\\"hide\\"/>\\n                                    <field name=\\"user_ids\\" column_invisible=\\"True\\"/>\\n                                    <field name=\\"portal_user_names\\" string=\\"Assignees\\" optional=\\"show\\"/>\\n                                    <field name=\\"date_deadline\\" decoration-danger=\\"date_deadline &lt; current_date and state not in ['1_done', '1_canceled']\\" optional=\\"show\\"/>\\n                                    <field name=\\"priority\\" widget=\\"priority\\" optional=\\"show\\" nolabel=\\"1\\" width=\\"20px\\"/>\\n                                    <field name=\\"tag_ids\\" widget=\\"many2many_tags\\" options=\\"{'color_field': 'color'}\\" optional=\\"hide\\"/>\\n                                    <field name=\\"stage_id\\" domain=\\"[('user_id', '=', False), ('project_ids', 'in', [project_id])]\\"/>\\n                                    <button name=\\"action_open_task\\" type=\\"object\\" title=\\"View Task\\" string=\\"View Task\\" class=\\"btn btn-link float-end\\" context=\\"{'form_view_ref': 'project.project_sharing_project_task_view_form', 'search_view_ref': 'project.project_sharing_project_task_view_search'}\\" invisible=\\"project_id != context.get('active_id')\\"/>\\n                                </list>\\n                            </field>\\n                        </page>\\n                        <page name=\\"task_dependencies\\" string=\\"Blocked By\\" invisible=\\"not allow_task_dependencies\\">\\n                            <field name=\\"depend_on_ids\\" widget=\\"depend_on_ids_one2many\\" nolabel=\\"1\\" options=\\"{'link': false}\\" readonly=\