1135	16	\N	1	1	account_invoice_facturx_export_22	\N	account_edi_ubl_cii.account_invoice_facturx_export_22	qweb	account_edi_ubl_cii/data/cii_22_templates.xml	primary	{"en_US": "<t t-name=\\"account_edi_ubl_cii.account_invoice_facturx_export_22\\">\\n            <t t-set=\\"currency\\" t-value=\\"record.currency_id or record.company_currency_id\\"/>\\n            <rsm:CrossIndustryInvoice xmlns:ram=\\"urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100\\" xmlns:rsm=\\"urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100\\" xmlns:udt=\\"urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100\\" xmlns:qdt=\\"urn:un:unece:uncefact:data:standard:QualifiedDataType:100\\" xmlns:xsi=\\"http://www.w3.org/2001/XMLSchema-instance\\">\\n                <!-- Factur-x level:\\n                    * minimum or basicwl:   urn:factur-x.eu:1p0...\\n                    * basic:                urn:cen.eu:en16931:2017:compliant:factur-x.eu:1p0:basic\\n                    * en16931:              urn:cen.eu:en16931:2017\\n                -->\\n                <rsm:ExchangedDocumentContext>\\n                    <ram:GuidelineSpecifiedDocumentContextParameter>\\n                        <ram:ID t-out=\\"document_context_id\\"/>\\n                    </ram:GuidelineSpecifiedDocumentContextParameter>\\n                </rsm:ExchangedDocumentContext>\\n\\n                <!-- Document Headers. -->\\n                <rsm:ExchangedDocument>\\n                    <ram:ID t-out=\\"ExchangedDocument_vals.get('id')\\"/>\\n                    <ram:TypeCode t-out=\\"ExchangedDocument_vals.get('type_code')\\"/>\\n                    <ram:IssueDateTime t-if=\\"ExchangedDocument_vals.get('issue_date_time')\\">\\n                        <udt:DateTimeString format=\\"102\\" t-out=\\"format_date(ExchangedDocument_vals.get('issue_date_time'))\\"/>\\n                    </ram:IssueDateTime>\\n                    <ram:IncludedNote>\\n                        <ram:Content t-out=\\"ExchangedDocument_vals.get('included_note')\\"/>\\n                    </ram:IncludedNote>\\n                    <ram:IncludedNote t-foreach=\\"ExchangedDocument_vals.get('included_note_list')\\" t-as=\\"included_note\\">\\n                        <ram:Content t-out=\\"included_note.get('content')\\"/>\\n                        <ram:SubjectCode t-out=\\"included_note.get('subject_code')\\"/>\\n                    </ram:IncludedNote>\\n                </rsm:ExchangedDocument>\\n\\n                <rsm:SupplyChainTradeTransaction>\\n                    <!-- Invoice lines. -->\\n                    <t t-foreach=\\"invoice_line_vals_list\\" t-as=\\"line_vals\\">\\n                        <t t-call=\\"account_edi_ubl_cii.account_invoice_line_facturx_export_22\\"/>\\n                    </t>\\n\\n                    <!-- Partners. -->\\n                    <ram:ApplicableHeaderTradeAgreement>\\n                        <!-- \\"Service Exécutant\\" (Used by Chorus Pro) -->\\n                        <ram:BuyerReference t-out=\\"buyer_reference\\"/>\\n                        <!-- Seller. -->\\n                        <ram:SellerTradeParty>\\n                            <!-- Address. -->\\n                            <t t-call=\\"account_edi_ubl_cii.account_invoice_partner_facturx_export_22\\">\\n                                <t t-set=\\"partner\\" t-value=\\"record.company_id.partner_id\\"/>\\n                                <t t-set=\\"specified_legal_organization_val\\" t-value=\\"seller_specified_legal_organization\\"/>\\n                            </t>\\n\\n                            <ram:URIUniversalCommunication t-if=\\"record.company_id.partner_id.peppol_eas and record.company_id.partner_id.peppol_endpoint\\">\\n                                <ram:URIID t-att-schemeID=\\"record.company_id.partner_id.peppol_eas\\" t-out=\\"record.company_id.partner_id.peppol_endpoint\\"/>\\n                            </ram:URIUniversalCommunication>\\n\\n                            <!-- VAT (BR-CO-09: '/' is not a valid VAT id). -->\\n                            <ram:SpecifiedTaxRegistration t-if=\\"record.fiscal_position_id.foreign_vat and record.fiscal_position_id.foreign_vat not in ['/', 'na', 'NA']\\">\\n                                <ram:ID schemeID=\\"VA\\" t-out=\\"record.fiscal_position_id.foreign_vat\\"/>\\n                            </ram:SpecifiedTaxRegistration>\\n\\n                            <ram:SpecifiedTaxRegistration t-elif=\\"record.company_id.vat and record.company_id.vat not in ['/', 'na', 'NA']\\">\\n                                <ram:ID schemeID=\\"VA\\" t-out=\\"record.company_id.vat\\"/>\\n                            </ram:SpecifiedTaxRegistration>\\n\\n                            <t t-foreach=\\"seller_extra_tax_registrations\\" t-as=\\"tax_registration\\">\\n                                <ram:SpecifiedTaxRegistration>\\n                                    <ram:ID t-att-schemeID=\\"tax_registration['scheme']\\" t-out=\\"tax_registration['value']\\"/>\\n                                </ram:SpecifiedTaxRegistration>\\n                            </t>\\n                        </ram:SellerTradeParty>\\n\\n                        <!-- Customer. -->\\n                        <ram:BuyerTradeParty>\\n                            <!-- Address. -->\\n                            <t t-call=\\"account_edi_ubl_cii.account_invoice_partner_facturx_export_22\\">\\n                                <t t-set=\\"partner\\" t-value=\\"record.partner_id\\"/>\\n                                <t t-set=\\"specified_legal_organization_val\\" t-value=\\"buyer_specified_legal_organization\\"/>\\n                            </t>\\n\\n                            <ram:URIUniversalCommunication t-if=\\"record.partner_id.peppol_eas and record.partner_id.peppol_endpoint\\">\\n                                <ram:URIID t-att-schemeID=\\"record.partner_id.peppol_eas\\" t-out=\\"record.partner_id.peppol_endpoint\\"/>\\n                            </ram:URIUniversalCommunication>\\n\\n                            <!-- VAT (BR-CO-09: '/' is not a valid VAT id). -->\\n                            <ram:SpecifiedTaxRegistration t-if=\\"record.commercial_partner_id.vat and record.commercial_partner_id.vat not in ['/', 'na', 'NA']\\">\\n                                <ram:ID schemeID=\\"VA\\" t-out=\\"record.commercial_partner_id.vat\\"/>\\n                            </ram:SpecifiedTaxRegistration>\\n                        </ram:BuyerTradeParty>\\n\\n                        <!-- Reference. -->\\n                        <ram:BuyerOrderReferencedDocument>\\n                            <!-- \\"Engagement Juridique\\" (used by Chorus Pro) -->\\n                            <ram:IssuerAssignedID t-out=\\"purchase_order_reference\\"/>\\n                        </ram:BuyerOrderReferencedDocument>\\n                        <ram:ContractReferencedDocument>\\n                            <!-- \\"Numéro de Marché\\" (Used by Chorus Pro) -->\\n                            <ram:IssuerAssignedID t-out=\\"contract_reference\\"/>\\n                        </ram:ContractReferencedDocument>\\n                    </ram:ApplicableHeaderTradeAgreement>\\n\\n                    <!-- Delivery -->\\n                    <ram:ApplicableHeaderTradeDelivery>\\n                        <ram:ShipToTradeParty>\\n                            <t t-call=\\"account_edi_ubl_cii.account_invoice_partner_facturx_export_22\\">\\n                                <t t-set=\\"partner\\" t-value=\\"ship_to_trade_party\\"/>\\n                                <t t-set=\\"hide_dtc\\" t-value=\\"document_context_id == 'urn:cen.eu:en16931:2017#compliant#urn:xoev-de:kosit:standard:xrechnung_2.2'\\"/>\\n                            </t>\\n                        </ram:ShipToTradeParty>\\n\\n                        <ram:ActualDeliverySupplyChainEvent t-if=\\"scheduled_delivery_time\\">\\n                            <ram:OccurrenceDateTime>\\n                                <udt:DateTimeString t-att-format=\\"102\\" t-out=\\"format_date(scheduled_delivery_time)\\"/>\\n                            </ram:OccurrenceDateTime>\\n                        </ram:ActualDeliverySupplyChainEvent>\\n                    </ram:ApplicableHeaderTradeDelivery>\\n\\n                    <!-- Taxes. -->\\n                    <ram:ApplicableHeaderTradeSettlement>\\n\\n                        <ram:PaymentReference t-out=\\"record.payment_reference\\"/>\\n                        <ram:InvoiceCurrencyCode t-out=\\"currency.name\\"/>\\n\\n                        <!-- Bank account. -->\\n                        <ram:SpecifiedTradeSettlementPaymentMeans t-if=\\"record.partner_bank_id.sanitized_acc_number\\">\\n                            <ram:TypeCode t-out=\\"payment_means_code\\"/>\\n                            <ram:PayeePartyCreditorFinancialAccount>\\n                                <ram:IBANID t-if=\\"record.partner_bank_id.acc_type == 'iban'\\" t-out=\\"record.partner_bank_id.sanitized_acc_number\\"/>\\n                                <ram:ProprietaryID t-if=\\"record.partner_bank_id.acc_type != 'iban'\\" t-out=\\"record.partner_bank_id.sanitized_acc_number\\"/>\\n                            </ram:PayeePartyCreditorFinancialAccount>\\n                        </ram:SpecifiedTradeSettlementPaymentMeans>\\n\\n                        <!-- Tax Summary. -->\\n                        <t t-foreach=\\"tax_details.get('tax_details', {}).values()\\" t-as=\\"tax_detail_vals\\">\\n                            <ram:ApplicableTradeTax>\\n                                <ram:CalculatedAmount t-out=\\"format_monetary(tax_detail_vals.get('calculated_amount'), 2)\\"/>\\n                                <ram:TypeCode t-translation=\\"off\\">VAT</ram:TypeCode>\\n                                <ram:ExemptionReason t-out=\\"tax_detail_vals.get('tax_exemption_reason')\\"/>\\n                                <ram:BasisAmount t-out=\\"format_monetary(tax_detail_vals['base_amount_currency'], 2)\\"/>\\n                                <ram:CategoryCode t-out=\\"tax_detail_vals['tax_category_code']\\"/>\\n                                <ram:ExemptionReasonCode t-out=\\"tax_detail_vals['tax_exemption_reason_code']\\"/>\\n                                <!-- 5 = Tax is exigible on the date on the invoice -->\\n                                <ram:DueDateTypeCode>5</ram:DueDateTypeCode>\\n                                <ram:RateApplicablePercent t-if=\\"tax_detail_vals['amount_type'] == 'percent'\\" t-out=\\"tax_detail_vals['amount']\\"/>\\n                            </ram:ApplicableTradeTax>\\n                        </t>\\n\\n                        <!-- Billing Period -->\\n                        <ram:BillingSpecifiedPeriod t-if=\\"billing_start and billing_end\\">\\n                            <ram:StartDateTime>\\n                                <udt:DateTimeString format=\\"102\\" t-out=\\"format_date(billing_start)\\"/>\\n                            </ram:StartDateTime>\\n                            <ram:EndDateTime>\\n                                <udt:DateTimeString format=\\"102\\" t-out=\\"format_date(billing_end)\\"/>\\n                            </ram:EndDateTime>\\n                        </ram:BillingSpecifiedPeriod>\\n\\n                        <!-- Payment Term. -->\\n                        <ram:SpecifiedTradePaymentTerms>\\n                            <ram:Description t-if=\\"record.invoice_payment_term_id\\" t-out=\\"record.invoice_payment_term_id.name\\"/>\\n                            <ram:DueDateDateTime t-if=\\"record.invoice_date_due\\">\\n                                <udt:DateTimeString format=\\"102\\" t-out=\\"format_date(record.invoice_date_due)\\"/>\\n                            </ram:DueDateDateTime>\\n                            <ram:ApplicableTradePaymentDiscountTerms t-if=\\"record.invoice_payment_term_id.early_discount and record.invoice_payment_term_id.early_pay_discount_computation == 'mixed'\\">\\n                                <ram:BasisPeriodMeasure unitCode=\\"DAY\\" t-out=\\"record.invoice_payment_term_id.discount_days\\"/>\\n                                <ram:CalculationPercent t-out=\\"record.invoice_payment_term_id.discount_percentage\\"/>\\n                            </ram:ApplicableTradePaymentDiscountTerms>\\n                        </ram:SpecifiedTradePaymentTerms>\\n\\n                        <!-- Summary. -->\\n                        <ram:SpecifiedTradeSettlementHeaderMonetarySummation>\\n                            <ram:LineTotalAmount t-esc=\\"format_monetary(tax_basis_total_amount, 2)\\"/>\\n                            <ram:TaxBasisTotalAmount t-esc=\\"format_monetary(tax_basis_total_amount, 2)\\"/>\\n                            <ram:TaxTotalAmount t-att-currencyID=\\"currency.name\\" t-esc=\\"format_monetary(tax_total_amount, 2)\\"/>\\n                            <ram:GrandTotalAmount t-out=\\"format_monetary(record.amount_total, 2)\\"/>\\n                            <ram:TotalPrepaidAmount t-out=\\"format_monetary(record.amount_total - record.amount_residual, 2)\\"/>\\n                            <ram:DuePayableAmount t-out=\\"format_monetary(record.amount_residual, 2)\\"/>\\n                        </ram:SpecifiedTradeSettlementHeaderMonetarySummation>\\n                    </ram:ApplicableHeaderTradeSettlement>\\n                </rsm:SupplyChainTradeTransaction>\\n            </rsm:CrossIndustryInvoice>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="account_edi_ubl_cii.account_invoice_facturx_export_22">\n            <t t-set="currency" t-value="record.currency_id or record.company_currency_id"/>\n            <rsm:CrossIndustryInvoice xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100" xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:udt="urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100" xmlns:qdt="urn:un:unece:uncefact:data:standard:QualifiedDataType:100" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">\n                <!-- Factur-x level:\n                    * minimum or basicwl:   urn:factur-x.eu:1p0...\n                    * basic:                urn:cen.eu:en16931:2017:compliant:factur-x.eu:1p0:basic\n                    * en16931:              urn:cen.eu:en16931:2017\n                -->\n                <rsm:ExchangedDocumentContext>\n                    <ram:GuidelineSpecifiedDocumentContextParameter>\n                        <ram:ID t-out="document_context_id"/>\n                    </ram:GuidelineSpecifiedDocumentContextParameter>\n                </rsm:ExchangedDocumentContext>\n\n                <!-- Document Headers. -->\n                <rsm:ExchangedDocument>\n                    <ram:ID t-out="ExchangedDocument_vals.get('id')"/>\n                    <ram:TypeCode t-out="ExchangedDocument_vals.get('type_code')"/>\n                    <ram:IssueDateTime t-if="ExchangedDocument_vals.get('issue_date_time')">\n                        <udt:DateTimeString format="102" t-out="format_date(ExchangedDocument_vals.get('issue_date_time'))"/>\n                    </ram:IssueDateTime>\n                    <ram:IncludedNote>\n                        <ram:Content t-out="ExchangedDocument_vals.get('included_note')"/>\n                    </ram:IncludedNote>\n                    <ram:IncludedNote t-foreach="ExchangedDocument_vals.get('included_note_list')" t-as="included_note">\n                        <ram:Content t-out="included_note.get('content')"/>\n                        <ram:SubjectCode t-out="included_note.get('subject_code')"/>\n                    </ram:IncludedNote>\n                </rsm:ExchangedDocument>\n\n                <rsm:SupplyChainTradeTransaction>\n                    <!-- Invoice lines. -->\n                    <t t-foreach="invoice_line_vals_list" t-as="line_vals">\n                        <t t-call="account_edi_ubl_cii.account_invoice_line_facturx_export_22"/>\n                    </t>\n\n                    <!-- Partners. -->\n                    <ram:ApplicableHeaderTradeAgreement>\n                        <!-- "Service Exécutant" (Used by Chorus Pro) -->\n                        <ram:BuyerReference t-out="buyer_reference"/>\n                        <!-- Seller. -->\n                        <ram:SellerTradeParty>\n                            <!-- Address. -->\n                            <t t-call="account_edi_ubl_cii.account_invoice_partner_facturx_export_22">\n                                <t t-set="partner" t-value="record.company_id.partner_id"/>\n                                <t t-set="specified_legal_organization_val" t-value="seller_specified_legal_organization"/>\n                            </t>\n\n                            <ram:URIUniversalCommunication t-if="record.company_id.partner_id.peppol_eas and record.company_id.partner_id.peppol_endpoint">\n                                <ram:URIID t-att-schemeID="record.company_id.partner_id.peppol_eas" t-out="record.company_id.partner_id.peppol_endpoint"/>\n                            </ram:URIUniversalCommunication>\n\n                            <!-- VAT (BR-CO-09: '/' is not a valid VAT id). -->\n                            <ram:SpecifiedTaxRegistration t-if="record.fiscal_position_id.foreign_vat and record.fiscal_position_id.foreign_vat not in ['/', 'na', 'NA']">\n                                <ram:ID schemeID="VA" t-out="record.fiscal_position_id.foreign_vat"/>\n                            </ram:SpecifiedTaxRegistration>\n\n                            <ram:SpecifiedTaxRegistration t-elif="record.company_id.vat and record.company_id.vat not in ['/', 'na', 'NA']">\n                                <ram:ID schemeID="VA" t-out="record.company_id.vat"/>\n                            </ram:SpecifiedTaxRegistration>\n\n                            <t t-foreach="seller_extra_tax_registrations" t-as="tax_registration">\n                                <ram:SpecifiedTaxRegistration>\n                                    <ram:ID t-att-schemeID="tax_registration['scheme']" t-out="tax_registration['value']"/>\n                                </ram:SpecifiedTaxRegistration>\n                            </t>\n                        </ram:SellerTradeParty>\n\n                        <!-- Customer. -->\n                        <ram:BuyerTradeParty>\n                            <!-- Address. -->\n                            <t t-call="account_edi_ubl_cii.account_invoice_partner_facturx_export_22">\n                                <t t-set="partner" t-value="record.partner_id"/>\n                                <t t-set="specified_legal_organization_val" t-value="buyer_specified_legal_organization"/>\n                            </t>\n\n                            <ram:URIUniversalCommunication t-if="record.partner_id.peppol_eas and record.partner_id.peppol_endpoint">\n                                <ram:URIID t-att-schemeID="record.partner_id.peppol_eas" t-out="record.partner_id.peppol_endpoint"/>\n                            </ram:URIUniversalCommunication>\n\n                            <!-- VAT (BR-CO-09: '/' is not a valid VAT id). -->\n                            <ram:SpecifiedTaxRegistration t-if="record.commercial_partner_id.vat and record.commercial_partner_id.vat not in ['/', 'na', 'NA']">\n                                <ram:ID schemeID="VA" t-out="record.commercial_partner_id.vat"/>\n                            </ram:SpecifiedTaxRegistration>\n                        </ram:BuyerTradeParty>\n\n                        <!-- Reference. -->\n                        <ram:BuyerOrderReferencedDocument>\n                            <!-- "Engagement Juridique" (used by Chorus Pro) -->\n                            <ram:IssuerAssignedID t-out="purchase_order_reference"/>\n                        </ram:BuyerOrderReferencedDocument>\n                        <ram:ContractReferencedDocument>\n                            <!-- "Numéro de Marché" (Used by Chorus Pro) -->\n                            <ram:IssuerAssignedID t-out="contract_reference"/>\n                        </ram:ContractReferencedDocument>\n                    </ram:ApplicableHeaderTradeAgreement>\n\n                    <!-- Delivery -->\n                    <ram:ApplicableHeaderTradeDelivery>\n                        <ram:ShipToTradeParty>\n                            <t t-call="account_edi_ubl_cii.account_invoice_partner_facturx_export_22">\n                                <t t-set="partner" t-value="ship_to_trade_party"/>\n                                <t t-set="hide_dtc" t-value="document_context_id == 'urn:cen.eu:en16931:2017#compliant#urn:xoev-de:kosit:standard:xrechnung_2.2'"/>\n                            </t>\n                        </ram:ShipToTradeParty>\n\n                        <ram:ActualDeliverySupplyChainEvent t-if="scheduled_delivery_time">\n                            <ram:OccurrenceDateTime>\n                                <udt:DateTimeString t-att-format="102" t-out="format_date(scheduled_delivery_time)"/>\n                            </ram:OccurrenceDateTime>\n                        </ram:ActualDeliverySupplyChainEvent>\n                    </ram:ApplicableHeaderTradeDelivery>\n\n                    <!-- Taxes. -->\n                    <ram:ApplicableHeaderTradeSettlement>\n\n                        <ram:PaymentReference t-out="record.payment_reference"/>\n                        <ram:InvoiceCurrencyCode t-out="currency.name"/>\n\n                        <!-- Bank account. -->\n                        <ram:SpecifiedTradeSettlementPaymentMeans t-if="record.partner_bank_id.sanitized_acc_number">\n                            <ram:TypeCode t-out="payment_means_code"/>\n                            <ram:PayeePartyCreditorFinancialAccount>\n                                <ram:IBANID t-if="record.partner_bank_id.acc_type == 'iban'" t-out="record.partner_bank_id.sanitized_acc_number"/>\n                                <ram:ProprietaryID t-if="record.partner_bank_id.acc_type != 'iban'" t-out="record.partner_bank_id.sanitized_acc_number"/>\n                            </ram:PayeePartyCreditorFinancialAccount>\n                        </ram:SpecifiedTradeSettlementPaymentMeans>\n\n                        <!-- Tax Summary. -->\n                        <t t-foreach="tax_details.get('tax_details', {}).values()" t-as="tax_detail_vals">\n                            <ram:ApplicableTradeTax>\n                                <ram:CalculatedAmount t-out="format_monetary(tax_detail_vals.get('calculated_amount'), 2)"/>\n                                <ram:TypeCode t-translation="off">VAT</ram:TypeCode>\n                                <ram:ExemptionReason t-out="tax_detail_vals.get('tax_exemption_reason')"/>\n                                <ram:BasisAmount t-out="format_monetary(tax_detail_vals['base_amount_currency'], 2)"/>\n                                <ram:CategoryCode t-out="tax_detail_vals['tax_category_code']"/>\n                                <ram:ExemptionReasonCode t-out="tax_detail_vals['tax_exemption_reason_code']"/>\n                                <!-- 5 = Tax is exigible on the date on the invoice -->\n                                <ram:DueDateTypeCode>5</ram:DueDateTypeCode>\n                                <ram:RateApplicablePercent t-if="tax_detail_vals['amount_type'] == 'percent'" t-out="tax_detail_vals['amount']"/>\n                            </ram:ApplicableTradeTax>\n                        </t>\n\n                        <!-- Billing Period -->\n                        <ram:BillingSpecifiedPeriod t-if="billing_start and billing_end">\n                            <ram:StartDateTime>\n                                <udt:DateTimeString format="102" t-out="format_date(billing_start)"/>\n                            </ram:StartDateTime>\n                            <ram:EndDateTime>\n                                <udt:DateTimeString format="102" t-out="format_date(billing_end)"/>\n                            </ram:EndDateTime>\n                        </ram:BillingSpecifiedPeriod>\n\n                        <!-- Payment Term. -->\n                        <ram:SpecifiedTradePaymentTerms>\n                            <ram:Description t-if="record.invoice_payment_term_id" t-out="record.invoice_payment_term_id.name"/>\n                            <ram:DueDateDateTime t-if="record.invoice_date_due">\n                                <udt:DateTimeString format="102" t-out="format_date(record.invoice_date_due)"/>\n                            </ram:DueDateDateTime>\n                            <ram:ApplicableTradePaymentDiscountTerms t-if="record.invoice_payment_term_id.early_discount and record.invoice_payment_term_id.early_pay_discount_computation == 'mixed'">\n                                <ram:BasisPeriodMeasure unitCode="DAY" t-out="record.invoice_payment_term_id.discount_days"/>\n                                <ram:CalculationPercent t-out="record.invoice_payment_term_id.discount_percentage"/>\n                            </ram:ApplicableTradePaymentDiscountTerms>\n                        </ram:SpecifiedTradePaymentTerms>\n\n                        <!-- Summary. -->\n                        <ram:SpecifiedTradeSettlementHeaderMonetarySummation>\n                            <ram:LineTotalAmount t-esc="format_monetary(tax_basis_total_amount, 2)"/>\n                            <ram:TaxBasisTotalAmount t-esc="format_monetary(tax_basis_total_amount, 2)"/>\n                            <ram:TaxTotalAmount t-att-currencyID="currency.name" t-esc="format_monetary(tax_total_amount, 2)"/>\n                            <ram:GrandTotalAmount t-out="format_monetary(record.amount_total, 2)"/>\n                            <ram:TotalPrepaidAmount t-out="format_monetary(record.amount_total - record.amount_residual, 2)"/>\n                            <ram:DuePayableAmount t-out="format_monetary(record.amount_residual, 2)"/>\n                        </ram:SpecifiedTradeSettlementHeaderMonetarySummation>\n                    </ram:ApplicableHeaderTradeSettlement>\n                </rsm:SupplyChainTradeTransaction>\n            </rsm:CrossIndustryInvoice>\n        </t>\n\n        	f	t	2026-11-08 08:02:19.10738	2026-11-08 08:02:19.10738	f
1150	16	957	1	1	Payment on My Invoices	\N	account_payment.portal_invoice_page_inherit_payment	qweb	account_payment/views/account_portal_templates.xml	extension	{"en_US": "<data name=\\"Payment on My Invoices\\" inherit_id=\\"account.portal_invoice_page\\">\\n        <xpath expr=\\"//t[@t-call='portal.portal_record_sidebar']//h2[1]\\" position=\\"after\\">\\n            <t t-set=\\"pending_txs\\" t-value=\\"invoice.transaction_ids.filtered(lambda tx: tx.state in ('pending', 'authorized') and tx.provider_code not in ('none', 'custom'))\\"/>\\n            <div name=\\"invoice_paid_badge\\" t-if=\\"invoice.currency_id.is_zero(invoice.amount_residual)\\" class=\\"rounded text-bg-success fw-normal badge\\">\\n                <i class=\\"fa fa-fw fa-check-circle\\"/> Paid\\n            </div>\\n            <t t-if=\\"not invoice.currency_id.is_zero(invoice.amount_residual)\\">\\n                <div t-if=\\"invoice.payment_state == 'in_payment'\\" class=\\"rounded text-bg-info fw-normal badge\\">\\n                    <i class=\\"fa fa-fw fa-check-circle\\"/> Processing Payment\\n                </div>\\n                <div t-elif=\\"pending_txs\\" class=\\"rounded text-bg-info fw-normal badge\\">\\n                    <i class=\\"fa fa-fw fa-check-circle\\"/> Pending\\n                </div>\\n            </t>\\n        </xpath>\\n        <xpath expr=\\"//t[@t-call='portal.portal_record_sidebar']//div[hasclass('o_download_pdf')]\\" position=\\"before\\">\\n            <a t-if=\\"invoice._has_to_be_paid()\\" href=\\"#\\" class=\\"btn btn-primary\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#pay_with\\">\\n                <i class=\\"fa fa-fw fa-arrow-circle-right\\"/> Pay Now\\n            </a>\\n        </xpath>\\n        <xpath expr=\\"//div[@id='invoice_content']//div[hasclass('o_portal_html_view')]\\" position=\\"before\\">\\n            <t t-set=\\"tx\\" t-value=\\"invoice.get_portal_last_transaction()\\"/>\\n            <div t-if=\\"invoice.get_portal_last_transaction() and invoice.amount_total and not success and not error and (invoice.payment_state != 'not_paid' or tx.state in ('pending', 'authorized')) and (invoice.payment_state != 'paid' and tx.state == 'done')\\" class=\\"o_account_payment_tx_status\\" t-att-data-invoice-id=\\"invoice.id\\">\\n                <t t-call=\\"payment.state_header\\"/>\\n            </div>\\n            <div t-if=\\"invoice._has_to_be_paid()\\" id=\\"portal_pay\\" t-att-data-payment=\\"payment\\">\\n                <t t-call=\\"account_payment.portal_invoice_payment\\"/>\\n            </div>\\n            <div t-else=\\"\\" id=\\"portal_pay\\" t-att-data-payment=\\"payment\\">\\n                <t t-call=\\"account_payment.portal_invoice_payment_paid\\"/>\\n            </div>\\n        </xpath>\\n    </data>"}	<?xml version="1.0"?>\n<data name="Payment on My Invoices" inherit_id="account.portal_invoice_page">\n        <xpath expr="//t[@t-call='portal.portal_record_sidebar']//h2[1]" position="after">\n            <t t-set="pending_txs" t-value="invoice.transaction_ids.filtered(lambda tx: tx.state in ('pending', 'authorized') and tx.provider_code not in ('none', 'custom'))"/>\n            <div name="invoice_paid_badge" t-if="invoice.currency_id.is_zero(invoice.amount_residual)" class="rounded text-bg-success fw-normal badge">\n                <i class="fa fa-fw fa-check-circle"/> Paid\n            </div>\n            <t t-if="not invoice.currency_id.is_zero(invoice.amount_residual)">\n                <div t-if="invoice.payment_state == 'in_payment'" class="rounded text-bg-info fw-normal badge">\n                    <i class="fa fa-fw fa-check-circle"/> Processing Payment\n                </div>\n                <div t-elif="pending_txs" class="rounded text-bg-info fw-normal badge">\n                    <i class="fa fa-fw fa-check-circle"/> Pending\n                </div>\n            </t>\n        </xpath>\n        <xpath expr="//t[@t-call='portal.portal_record_sidebar']//div[hasclass('o_down