_last_transaction()\\"/>\\n        </xpath>\\n        <xpath expr=\\"//span[@name='invoice_status_waiting_for_payment']\\" position=\\"before\\">\\n            <span t-elif=\\"invoice.payment_state in ('not_paid', 'partial') and tx_sudo.state == 'authorized'\\" class=\\"badge rounded-pill text-bg-primary\\">\\n                <i class=\\"fa fa-fw fa-check\\"/>\\n                <span class=\\"d-none d-md-inline\\"> Authorized</span>\\n            </span>\\n            <span t-elif=\\"invoice.payment_state in ('not_paid', 'partial') and tx_sudo.state == 'pending' and tx_sudo.provider_code not in ('none', 'custom')\\" class=\\"badge rounded-pill text-bg-warning\\">\\n                <span class=\\"d-none d-md-inline\\"> Pending</span>\\n            </span>\\n            <span t-elif=\\"invoice.payment_state in ('paid', 'in_payment') and tx_sudo.state == 'done'\\" class=\\"badge rounded-pill text-bg-success\\">\\n                <i class=\\"fa fa-fw fa-check\\"/>\\n                <span class=\\"d-none d-md-inline\\"> Paid</span>\\n            </span>\\n        </xpath>\\n    </data>"}	<?xml version="1.0"?>\n<data name="Payment on My Invoices" inherit_id="account.portal_my_invoices">\n        <xpath expr="//t[@t-call='portal.portal_table']//th[@name='status']" position="after">\n            <th class="d-none d-lg-table-cell"/>\n            <th/>\n        </xpath>\n        <xpath expr="//t[@t-foreach='invoices']/tr/td[@name='invoice_status']" position="after">\n            <td class="d-none d-lg-table-cell text-center">\n                <t t-if="invoice_data.get('installment_state', False) in ('next', 'overdue')">\n                    <span t-attf-class="{{'text-danger' if invoice_data['installment_state'] == 'overdue' else ''}}" t-out="invoice_data['next_amount_to_pay']" t-options="{'widget': 'monetary', 'display_currency': invoice.currency_id}"/>\n                    <small t-if="invoice_data['installment_state'] == 'next'" class="o_portal_invoice_due_date" t-att-date