r\\" invisible=\\"not module_sale_amazon\\"/>\\n                        </setting>\\n                        <setting id=\\"gelato\\" documentation=\\"/applications/sales/sales/gelato.html\\" help=\\"Place orders through Gelato's print-on-demand service\\">\\n                            <field name=\\"module_sale_gelato\\"/>\\n                            <div class=\\"content-group\\" name=\\"gelato_credentials\\" invisible=\\"not module_sale_gelato\\"/>\\n                        </setting>\\n                        <setting id=\\"shopee_connector\\" help=\\"Import Shopee orders and sync deliveries\\">\\n                            <field name=\\"module_sale_shopee\\" widget=\\"upgrade_boolean\\"/>\\n                        </setting>\\n                    </block>\\n                </app>\\n            </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                <app notApp="1" string="Sales" data-string="Sales" name="sale_management" groups="sales_team.group_sale_manager">\n                    <block title="Product Catalog" name="catalog_setting_container">\n                        <setting id="variant_options" help="Sell variants of a product using attributes (size, color, etc.)" documentation="/applications/sales/sales/products_prices/products/variants.html">\n                            <field name="group_product_variant"/>\n                            <div class="content-group" invisible="not group_product_variant">\n                                <div class="mt8">\n                                    <button name="250" icon="oi-arrow-right" type="action" string="Attributes" class="btn-link"/>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting string="Variant Grid Entry" help="Add several variants to an order from a grid" id="product_matrix">\n                            <field name="module_sale_product_matrix"/>\n                      