filter name=\\"reception\\" invisible=\\"1\\" string=\\"Receipts\\" domain=\\"[('picking_type_code', '=', 'incoming')]\\"/>\\n                    <filter name=\\"delivery\\" invisible=\\"1\\" string=\\"Deliveries\\" domain=\\"[('picking_type_code', '=', 'outgoing')]\\"/>\\n                    <filter name=\\"internal\\" invisible=\\"1\\" string=\\"Internal\\" domain=\\"[('picking_type_code', '=', 'internal')]\\"/>\\n                    <separator/>\\n                    <filter invisible=\\"1\\" name=\\"before\\" string=\\"Before\\" domain=\\"[('search_date_category', '=', 'before')]\\"/>\\n                    <filter name=\\"late\\" string=\\"Late\\" help=\\"Deadline exceed or/and by the scheduled\\" domain=\\"[('state', 'in', ('assigned', 'waiting', 'confirmed')), '|', '|', ('has_deadline_issue', '=', True), ('date_deadline', '&lt;', current_date), ('scheduled_date', '&lt;', current_date)]\\"/>\\n                    <filter name=\\"yesterday\\" string=\\"Yesterday\\" domain=\\"[('search_date_category', '=', 'yesterday')]\\"/>\\n                    <filter name=\\"today\\" string=\\"Today\\" domain=\\"[('search_date_category', '=', 'today')]\\"/>\\n                    <filter name=\\"day_1\\" string=\\"Tomorrow\\" domain=\\"[('search_date_category', '=', 'day_1')]\\"/>\\n                    <filter invisible=\\"1\\" name=\\"day_2\\" string=\\"The day after tomorrow\\" domain=\\"[('search_date_category', '=', 'day_2')]\\"/>\\n                    <filter invisible=\\"1\\" name=\\"after\\" string=\\"After\\" domain=\\"[('search_date_category', '=', 'after')]\\"/>\\n                    <separator/>\\n                    <filter string=\\"Late Availability\\" name=\\"late_availability\\" domain=\\"[('products_availability_state', '=', 'late')]\\"/>\\n                    <separator/>\\n                    <filter name=\\"backorder\\" string=\\"Backorders\\" domain=\\"[('backorder_id', '!=', False), ('state', 'in', ('assigned', 'waiting', 'confirmed'))]\\" help=\\"Remaining parts of picking partially processed\\"/>\\n                    <separator/>\\n                    <filter invisible=\\"1\\" string=\\"My Activities\\" name=\\"filter_activities_my\\" domain=\\"[('activity_user_id', '=', uid)]\\"/>\\n                    <separator invisible=\\"1\\"/>\\n                    <filter invisible=\\"1\\" string=\\"Late Activities\\" name=\\"activities_overdue\\" domain=\\"[('my_activity_date_deadline', '&lt;', 'today')]\\" help=\\"Show all records whose next activity date is past\\"/>\\n                    <filter invisible=\\"1\\" string=\\"Today Activities\\" name=\\"activities_today\\" domain=\\"[('my_activity_date_deadline', '=', 'today')]\\"/>\\n                    <filter invisible=\\"1\\" string=\\"Future Activities\\" name=\\"activities_upcoming_all\\" domain=\\"[('my_activity_date_deadline', '&gt;', 'today')]\\"/>\\n                    <separator/>\\n                    <filter string=\\"Warnings\\" name=\\"activities_exception\\" domain=\\"[('activity_exception_decoration', '!=', False)]\\"/>\\n                    <group>\\n                        <filter string=\\"Status\\" name=\\"status\\" domain=\\"[]\\" context=\\"{'group_by': 'state'}\\"/>\\n                        <filter string=\\"Scheduled Date\\" name=\\"expected_date\\" domain=\\"[]\\" context=\\"{'group_by': 'scheduled_date'}\\"/>\\n                        <filter string=\\"Source Document\\" name=\\"origin\\" domain=\\"[]\\" context=\\"{'group_by': 'origin'}\\"/>\\n                        <filter string=\\"Destination Country\\" name=\\"partner_country\\" context=\\"{'group_by': 'partner_country_id'}\\"/>\\n                        <filter string=\\"Operation Type\\" name=\\"picking_type\\" domain=\\"[]\\" context=\\"{'group_by': 'picking_type_id'}\\"/>\\n                        <filter string=\\"Properties\\" name=\\"group_by_picking_properties\\" context=\\"{'group_by': 'picking_properties'}\\"/>\\n                    </group>\\n                </search>"}	<?xml 