1483	16	\N	1	1	Help Message	\N	stock.help_message_template	qweb	stock/views/stock_picking_views.xml	primary	{"en_US": "<t name=\\"Help Message\\" t-name=\\"stock.help_message_template\\">\\n            <p name=\\"top_help_message\\" class=\\"o_view_nocontent_smiling_face o_view_nocontent_stock\\">\\n                <t name=\\"receipt_message\\">\\n                    <t t-if=\\"picking_type_code == 'incoming'\\">\\n                        No receipt yet! Create a new one.\\n                    </t>\\n                </t>\\n                <t name=\\"delivery_message\\">\\n                    <t t-if=\\"picking_type_code == 'outgoing'\\">\\n                        No delivery to do!\\n                    </t>\\n                </t>\\n                <t name=\\"transfer_message\\">\\n                    <t t-if=\\"picking_type_code not in ['incoming', 'outgoing']\\">\\n                        No transfer found. Let's create one!\\n                    </t>\\n                </t>\\n            </p>\\n            <p name=\\"bottom_help_message\\" class=\\"text-muted\\">\\n                <t name=\\"receipt_message\\">\\n                    <t t-if=\\"picking_type_code == 'incoming'\\">\\n                        Reduce stockouts with alerts, barcode app, replenishment propositions,\\n                        locations management traceability, quality control, etc.\\n                    </t>\\n                </t>\\n                <t name=\\"delivery_message\\">\\n                    <t t-if=\\"picking_type_code == 'outgoing'\\"/>\\n                </t>\\n                <t name=\\"transfer_message\\">\\n                    <t t-if=\\"picking_type_code not in ['incoming', 'outgoing']\\">\\n                        Transfers allow you to move products from one location to another.\\n                    </t>\\n                </t>\\n            </p>\\n            <p name=\\"footer_help_message\\" class=\\"text-muted\\">\\n                <br/>\\n                Want to speed up operations? <a class=\\"btn-link\\" name=\\"stock.action_install_barcode\\" type=\\"action\\">Install</a> the barcode app\\n            </p>\\n        </t>"}	<?xml version="1.0"?>\n<t name="Help Message" t-name="stock.help_message_template">\n            <p name="top_help_message" class="o_view_nocontent_smiling_face o_view_nocontent_stock">\n                <t name="receipt_message">\n                    <t t-if="picking_type_code == 'incoming'">\n                        No receipt yet! Create a new one.\n                    </t>\n                </t>\n                <t name="delivery_message">\n                    <t t-if="picking_type_code == 'outgoing'">\n                        No delivery to do!\n                    </t>\n                </t>\n                <t name="transfer_message">\n                    <t t-if="picking_type_code not in ['incoming', 'outgoing']">\n                        No transfer found. Let's create one!\n                    </t>\n                </t>\n            </p>\n            <p name="bottom_help_message" class="text-muted">\n                <t name="receipt_message">\n                    <t t-if="picking_type_code == 'incoming'">\n                        Reduce stockouts with alerts, barcode app, replenishment propositions,\n                        locations management traceability, quality control, etc.\n                    </t>\n                </t>\n                <t name="delivery_message">\n                    <t t-if="picking_type_code == 'outgoing'"/>\n                </t>\n                <t name="transfer_message">\n                    <t t-if="picking_type_code not in ['incoming', 'outgoing']">\n                        Transfers allow you to move products from one location to another.\n                    </t>\n                </t>\n            </p>\n            <p name="footer_help_message" class="text-muted">\n                <br/>\n                Want to speed up operations? <a class="btn-link" name="stock.action_install_barcode" type="action">Install</a> the barcode app\n            </p>\n        </t>\n\n        	f	t	2026-11-09 19:12:12.017056	2026-11-09 19:12:12.017056	f
