>\n                            <div class="o_field_statinfo">\n                                <span class="o_stat_text">Bill Matching</span>\n                            </div>\n                        </button>\n                        <button type="object" name="action_view_invoice" class="oe_stat_button" icon="fa-pencil-square-o" invisible="invoice_count == 0 or state in ('draft', 'sent', 'to approve')">\n                            <field name="invoice_count" widget="statinfo" string="Vendor Bills"/>\n                            <field name="invoice_ids" invisible="1"/>\n                        </button>\n                        <button type="object" name="action_purchase_comparison" class="oe_stat_button" invisible="not show_comparison" icon="fa-dollar">\n                            <div class="o_field_statinfo">\n                                <span class="o_stat_text">Price Comparison</span>\n                            </div>\n                            <field name="show_comparison" invisible="1"/>\n                        </button>\n                    </div>\n                    <div class="badge rounded-pill text-bg-secondary float-end fs-6 border-0" invisible="not locked">\n                        <i class="fa fa-lock"/>\n                        Locked\n                    </div>\n                    <div class="oe_title">\n                        <span class="o_form_label" invisible="state not in ('draft', 'sent')">Request for Quotation </span>\n                        <span class="o_form_label" invisible="state in ('draft', 'sent')">Purchase Order </span>\n                        <h1 class="d-flex">\n                            <field name="priority" widget="priority" class="me-3"/>\n                            <field name="name" readonly="1"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name="partner_id" widget="res_partner_many2one" con