" class="text-end">\n                          <span class="d-none d-md-inline">Confirmation Date</span>\n                          <span class="d-block d-md-none">Confirmation</span>\n                      </th>\n                      <th id="order_badge_header" class="text-center"/>\n                      <th id="order_total_header" class="text-end">Total</th>\n                  </tr>\n              </thead>\n              <t t-foreach="orders" t-as="order">\n                  <tr>\n                      <td id="order_name"><a t-att-href="order.get_portal_url()"><t t-esc="order.name"/></a></td>\n                      <td id="order_confirmation" class="text-end">\n                          <span t-field="order.date_approve" t-options="{'widget': 'date'}"/>&amp;nbsp;\n                          <span class="d-none d-md-inline" t-field="order.date_approve" t-options="{'time_only': True}"/>\n                      </td>\n                      <td id="order_badge" class="text-center">\n                          <span t-if="order.invoice_status == 'to invoice'" class="badge rounded-pill text-bg-info">\n                              <i class="fa fa-fw fa-file-text" role="img" aria-label="Waiting for Bill" title="Waiting for Bill"/><span class="d-none d-md-inline"> Waiting for Bill</span>\n                          </span>\n                          <span t-if="order.state == 'cancel'" class="badge rounded-pill text-bg-secondary">\n                              <i class="fa fa-fw fa-remove" role="img" aria-label="Cancelled" title="Cancelled"/><span class="d-none d-md-inline"> Cancelled</span>\n                          </span>\n                      </td>\n                      <td id="order_total" class="text-end"><span t-field="order.amount_total"/></td>\n                  </tr>\n              </t>\n          </t>\n      </t>\n  </t>\n\n  	f	t	2026-11-09 19:12:43.169083	2026-11-09 19:12:43.169083	f
1635	16	537	1	1	Purchase Order	\N	purchase.portal_my_purchase_order	qweb	purchase/views/portal_templates.xml	primary	{"en_US": "<data name=\\"Purchase Order\\" inherit_id=\\"portal.portal_sidebar\\" primary=\\"True\\">\\n      <xpath expr=\\"//div[hasclass('o_portal_sidebar')]\\" position=\\"inside\\">\\n          <t t-set=\\"o_portal_fullwidth_alert\\" groups=\\"purchase.group_purchase_manager\\">\\n              <t t-call=\\"portal.portal_back_in_edit_mode\\">\\n                  <t t-set=\\"backend_url\\" t-value=\\"'/odoo/action-purchase.purchase_rfq/%s' % (order.id)\\"/>\\n              </t>\\n          </t>\\n\\n          <div class=\\"row o_portal_purchase_sidebar\\">\\n              <!-- Sidebar -->\\n              <t t-call=\\"portal.portal_record_sidebar\\">\\n                  <t t-set=\\"classes\\" t-value=\\"'col-lg-4 col-xxl-3 d-print-none'\\"/>\\n\\n                  <t t-set=\\"title\\">\\n                      <h2 t-field=\\"order.amount_total\\" data-id=\\"total_amount\\" class=\\"mb-0 text-break\\"/>\\n                  </t>\\n                  <t t-set=\\"entries\\">\\n                      <div class=\\"d-flex flex-column gap-4 mt-3\\">\\n                          <a class=\\"btn btn-secondary o_print_btn o_portal_invoice_print\\" t-att-href=\\"order.get_portal_url(report_type='pdf')\\" id=\\"print_invoice_report\\" title=\\"View Details\\" role=\\"button\\" target=\\"_blank\\"><i class=\\"fa fa-print me-1\\"/>Download / Print</a>\\n                          <div class=\\"navspy flex-grow-1 ps-0\\" t-ignore=\\"true\\" role=\\"complementary\\">\\n                              <ul class=\\"nav flex-column bs-sidenav\\"/>\\n                          </div>\\n                          <div t-if=\\"order.user_id\\">\\n                              <h6 class=\\"small text-muted\\">Buyer</h6>\\n                                <t t-call=\\"portal.portal_my_contact\\">\\n                                    <t t-set=\\"_contactAvatar\\" t-value=\\"image_data_uri(order.user_id.avatar_128)\\"/>\\n                                    <t t-set=\\"_contactName\\" t-value=\\"order.user_id.name\\"/>\\n                                    <t t-set=\\"_contactLink\\" t-value=\\"True\\"/>\\n                                    <div t-field=\\"order.user_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;phone&quot;], &quot;no_marker&quot;: False}\\"/>\\n                                </t>\\n                          </div>\\n\\n                          <div t-if=\\"order._get_edi_builders()\\">\\n                            <button id=\\"portal_connect_software_modal_btn\\" type=\\"button\\" class=\\"btn btn-primary\\" data-bs-toggle=\\"modal\\" data-bs-target=\\"#portal_connect_software_modal\\">\\n                                Connect with your software!\\n                            </button>\\n                          </div>\\n                      </div>\\n                  </t>\\n              </t>\\n\\n              <div class=\\"modal fade\\" id=\\"portal_connect_software_modal\\" tabindex=\\"-1\\" role=\\"dialog\\" aria-hidden=\\"true\\">\\n                <div class=\\"modal-dialog modal-lg\\" role=\\"document\\">\\n                    <div class=\\"modal-content\\">\\n                        <div class=\\"modal-body\\">\\n                            <div>\\n                                <h5>Want to import this document in Odoo?</h5>\\n                                <p>Drag and drop the request for quotation PDF file into your list of quotations in Odoo. Enjoy the automation!</p>\\n                            </div>\\n                            <div>\\n                                <h5>Not using Odoo?</h5>\\n                                <div class=\\"input-group mb-3 w-50\\">\\n                                    <t t-set=\\"base_address\\" t-value=\\"order.env['ir.config_parameter'].sudo().get_param('web.base.url')\\"/>\\n                                    <t t-set=\\"doc_url\\" t-value=\\"base_address + '/my/purchase/' + str(order.id) + '/download_edi?' + str(keep_query())\\"/>\\n                                    <input type=\\"text\\" class=\\"form-control\\" aria-describedby=\\"copy-button\\" readonly=\\"readonly\\" t-att-value=\\"doc_url\\"/>\\n                                    <button class=\\"btn btn-outline-secondary\\" type=\\"button\\" id=\\"copy-button\\" t-attf-onclick=\\"navigator.clipboard.writeText('#{doc_url}')\\">Copy</button>\\n                                </div>\\n                                <p>Use the above REST URL to get structured data of the purchase order in UBL format.\\n                                    <a href=\\"https://www.odoo.com/documentation/\\">Read the documentation </a>to learn all the ways to connect your software with <a href=\\"https://www.odoo.com\\">Odoo</a>.\\n                                </p>\\n                            </div>\\n                            <div>\\n                                <h5>You don't use a good CRM software?</h5>\\n                                <p><a href=\\"https://www.odoo.com/app/sales\\">Start on Odoo</a>, it's 100% free! You'll save time creating beautiful quotations and track sales.</p>\\n                            </div>\\n                        </div>\\n                        <div class=\\"modal-footer justify-content-between\\">\\n                            <button type=\\"button\\" class=\\"btn btn-secondary\\" data-bs-dismiss=\\"modal\\">Close</button>\\n                        </div>\\n                    </div>\\n                </div>\\n              </div>\\n\\n              <!-- Page content -->\\n              <div id=\\"quote_content\\" class=\\"o_portal_content col-12 col-lg-8 col-xxl-9\\">\\n                  <!-- main content -->\\n                  <div id=\\"portal_purchase_content\\">\\n                      <div><t t-call=\\"purchase.purchase_order_portal_content\\"/></div>\\n                  </div>\\n\\n                  <!-- chatter -->\\n                  <hr/>\\n                  <div id=\\"purchase_order_communication\\">\\n                      <h3>Communication history</h3>\\n                      <t t-call=\\"portal.message_thread\\"/>\\n                  </div>\\n              </div><!-- // #quote_content -->\\n          </div>\\n      </xpath>\\n  <xpath expr=\\".\\" position=\\"attributes\\"><attribute name=\\"t-name\\">purchase.portal_my_purchase_order</attribute></xpath></data>"}	<?xml version="1.0"?>\n<data name="Purchase Order" inherit_id="portal.portal_sidebar" primary="True">\n      <xpath expr="//div[hasclass('o_portal_sidebar')]" position="inside">\n          <t t-set="o_portal_fullwidth_alert" groups="purchase.group_purchase_manager">\n              <t t-call="portal.portal_back_in_edit_mode">\n                  <t t-set="backend_url" t-value="'/odoo/action-purchase.purchase_rfq/%s' % (order.id)"/>\n              </t>\n          </t>\n\n          <div class="row o_portal_purchase_sidebar">\n              <!-- Sidebar -->\n              <t t-call="portal.portal_record_sidebar">\n                  <t t-set="classes" t-value="'col-lg-4 col-xxl-3 d-print-none'"/>\n\n                  <t t-set="title">\n                      <h2 t-field="order.amount_total" data-id="total_amount" class="mb-0 text-break"/>\n                  </t>\n                  <t t-set="entries">\n                      <div class="d-flex flex-column gap-4 mt-3">\n                          <a class="btn btn-secondary o_print_btn o_portal_invoice_print" t-att-href="order.get_portal_url(report_type='pdf')" id="print_invoice_report" title="View Details" role="button" target="_blank"><i class="fa fa-print me-1"/>Download / Print</a>\n                          <div class="navspy flex-grow-1 ps-0" t-ignore="true" role="complementary">\n                              <ul class="nav flex-column bs-sidenav"/>\n                          </div>\n                          <div t-if="order.user_id">\n                              <h6 class="small text-muted">Buyer</h6>\n                                <t t-call="portal.portal_my_contact">\n                                    <t t-set="_contactAvatar" t-value="image_data_uri(order.user_id.avatar_128)"/>\n                                    <t t-set="_contactName" t-value="order.user_id.name"/>\n                                    <t t-set="_contactLink" t-value="True"/>\n                                    <div t-field="order.user_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;phone&quot;], &quot;no_marker&quot;: False}"/>\n                                </t>\n                          </div>\n\n                          <div t-if="order._get_edi_builders()">\n                            <button id="portal_connect_software_modal_btn" type="button" class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#portal_connect_software_modal">\n                                Connect with your software!\n                            </button>\n                          </div>\n                      </div>\n                  </t>\n              </t>\n\n              <div class="modal fade" id="portal_connect_software_modal" tabindex="-1" role="dialog" aria-hidden="true">\n                <div class="modal-dialog modal-lg" role="document">\n                    <div class="modal-content">\n                        <div class="modal-body">\n                            <div>\n                                <h5>Want to import this document in Odoo?</h5>\n                                <p>Drag and drop the request for quotation PDF file into your list of quotations in Odoo. Enjoy the automation!</p>\n                            </div>\n                            <div>\n                                <h5>Not using Odoo?</h5>\n                                <div class="input-group mb-3 w-50">\n                                    <t t-set="base_address" t-value="order.env['ir.config_parameter'].sudo().get_param('web.base.url')"/>\n                                    <t t-set="doc_url" t-value="base_address + '/my/purchase/' + str(order.id) + '/download_edi?' + str(keep_query())"/>\n                                    <input type="text" class="form-control" aria-describedby="copy-button" readonly="readonly" t-att-value="doc_url"/>\n                                    <button class="btn btn-outline-secondary" type="button" id="copy-button" t-attf-onclick="navigator.clipboard.writeText('#{doc_url}')">Copy</button>\n                                </div>\n                                <p>Use the above REST URL to get structured data of the purchase order in UBL format.\n                                    <a href="https://www.odoo.com/documentation/">Read the documentation </a>to learn all the ways to connect your software with <a href="https://www.odoo.com">Odoo</a>.\n                                </p>\n                            </div>\n                            <div>\n                                <h5>You don't use a good CRM software?</h5>\n                                <p><a href="https://www.odoo.com/app/sales">Start on Odoo</a>, it's 100% free! You'll save time creating beautiful quotations and track sales.</p>\n                            </div>\n                        </div>\n                        <div class="modal-footer justify-content-between">\n                            <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Close</button>\n                        </div>\n                    </div>\n                </div>\n              </div>\n\n              <!-- Page content -->\n              <div id="quote_content" class="o_portal_content col-12 col-lg-8 col-xxl-9">\n                  <!-- main content -->\n                  <div id="portal_purchase_content">\n                      <div><t t-call="purchase.purchase_order_portal_content"/></div>\n                  </div>\n\n                  <!-- chatter -->\n                  <hr/>\n                  <div id="purchase_order_communication">\n                      <h3>Communication history</h3>\n                      <t t-call="portal.message_thread"/>\n                  </div>\n              </div><!-- // #quote_content -->\n          </div>\n      </xpath>\n  <xpath expr="." position="attributes"><attribute name="t-name">purchase.portal_my_purchase_order</attribute></xpath></data>\n\n  	f	t	2026-11-09 19:12:43.169083	2026-11-09 19:12:43.169083	f
1636	16	\N	1	1	Purchase Order Portal Content	\N	purchase.purchase_order_portal_content	qweb	purchase/views/portal_templates.xml	primary	{"en_US": "<t name=\\"Purchase Order Portal Content\\" t-name=\\"purchase.purchase_order_portal_content\\">\\n      <!-- Intro -->\\n      <div id=\\"introduction\\" class=\\"mt-5 mt-lg-0 pb-2 pt-0\\">\\n        <h2 class=\\"my-0\\">\\n          <t t-if=\\"order.state in ['draft', 'sent']\\">Request for Quotation</t>\\n          <t t-else=\\"1\\">\\n            Purchase Order\\n          </t>\\n          <em t-esc=\\"order.name\\"/>\\n        </h2>\\n      </div>\\n\\n      <div>\\n          <!-- Informations -->\\n          <div id=\\"informations\\">\\n              <div class=\\"row\\" id=\\"po_date\\">\\n                  <div class=\\"mb-3 col-6\\">\\n                    <t t-if=\\"order.state in ['draft', 'sent']\\">\\n                      <strong>Request For Quotation Date:</strong>\\n                    </t>\\n                    <t t-if=\\"order.state in ['purchase', 'cancel']\\">\\n                      <strong>Order Date:</strong>\\n                    </t>\\n                    <span t-field=\\"order.date_order\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/>\\n                  </div>\\n              </div>\\n              <div class=\\"row\\">\\n                  <div class=\\"col-lg-6\\">\\n                    <strong class=\\"d-block mb-1\\">From:</strong>\\n                    <address t-field=\\"order.company_id.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n                    <t t-if=\\"order.date_approve\\">\\n                      <strong>Confirmation Date:</strong> <span t-field=\\"order.date_approve\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/><br/>\\n                    </t>\\n                    <div t-att-class=\\"'d-inline' if order.date_planned else 'd-none'\\">\\n                      <strong>Receipt Date:</strong><span class=\\"ms-1\\" t-field=\\"order.date_planned\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\"/>\\n                    </div>\\n                  </div>\\n              </div>\\n\\n              <t t-set=\\"invoices\\" t-value=\\"[i for i in order.invoice_ids if i.state not in ['draft', 'cancel']]\\"/>\\n              <div t-if=\\"invoices\\" class=\\"row\\">\\n                  <div class=\\"col\\">\\n                      <strong class=\\"d-block mb-1\\">Invoices</strong>\\n                      <ul class=\\"list-group mb-4\\">\\n                          <t t-foreach=\\"invoices\\" t-as=\\"i\\">\\n                              <t t-set=\\"report_url\\" t-value=\\"i.get_portal_url(report_type='pdf', download=True)\\"/>\\n                              <div class=\\"d-flex flex-wrap align-items-center justify-content-between\\">\\n                                  <div>\\n                                      <a t-att-href=\\"report_url\\">\\n                                          <span t-esc=\\"i.name\\"/>\\n                                      </a>\\n                                      <div class=\\"small d-lg-inline-block\\">Date: <span class=\\"text-muted\\" t-field=\\"i.invoice_date\\"/></div>\\n                                  </div>\\n                                  <span t-if=\\"i.payment_state in ('paid', 'in_payment')\\" class=\\"badge rounded-pill text-bg-success small\\"><i class=\\"fa fa-fw fa-check\\"/>Paid</span>\\n                                  <span t-elif=\\"i.payment_state == 'reversed'\\" class=\\"badge rounded-pill text-bg-success small\\"><i class=\\"fa fa-fw fa-check\\"/>Reversed</span>\\n                                  <span t-else=\\"\\" class=\\"small badge rounded-pill text-bg-primary\\"><i class=\\"fa fa-fw fa-clock-o\\"/>Waiting Payment</span>\\n                              </div>\\n                          </t>\\n                      </ul>\\n                  </div>\\n              </div>\\n          </div>\\n\\n          <section id=\\"details\\" style=\\"page-break-inside: auto;\\" class=\\"mt32\\">\\n              <h3 id=\\"details\\">Pricing</h3>\\n\\n              <div class=\\"table-responsive\\">\\n                <table t-att-data-order-id=\\"order.id\\" t-att-data-token=\\"order.access_token\\" class=\\"table table-sm\\" id=\\"purchase_order_table\\">\\n                    <t t-set=\\"display_price_and_taxes\\" t-value=\\"not update_dates and order.state == 'purchase'\\"/>\\n                    <thead class=\\"bg-100\\">\\n                        <tr>\\n                            <th class=\\"text-start\\">Products</th>\\n                            <th class=\\"text-end\\">Quantity</th>\\n                            <th t-if=\\"update_dates\\" class=\\"text-end\\">Scheduled Date</th>\\n                            <th t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">Unit Price</th>\\n                            <th t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                <span>Taxes</span>\\n                            </th>\\n                            <th t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">Disc.%</th>\\n                            <th class=\\"text-end\\" t-if=\\"display_price_and_taxes\\">\\n                                <span>Amount</span>\\n                            </th>\\n                        </tr>\\n                    </thead>\\n                    <tbody class=\\"purchase_tbody\\">\\n\\n                          <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                          <t t-set=\\"filtered_lines\\" t-value=\\"order.order_line.filtered(lambda l: l.display_type or l.product_qty != 0)\\"/>\\n\\n                          <t t-foreach=\\"filtered_lines\\" t-as=\\"line\\">\\n\\n                              <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line.price_subtotal\\"/>\\n\\n                            <tr t-att-class=\\"'fw-bolder o_line_section' if line.display_type == 'line_section' else 'fw-bold o_line_subsection' if line.display_type == 'line_subsection' else 'fst-italic text-break o_line_note' if line.display_type == 'line_note' else ''\\">\\n                                <t t-if=\\"not line.display_type\\">\\n                                    <td id=\\"product_name\\" class=\\"d-flex\\">\\n                                        <img t-att-src=\\"line.product_id.image_128 and image_data_uri(line.product_id.image_128) or '/web/static/img/placeholder.png'\\" alt=\\"Product\\" class=\\"d-none d-lg-inline o_purchase_portal_product_image\\"/>\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\">\\n                                        <div id=\\"quote_qty\\">\\n                                            <span t-field=\\"line.product_qty\\"/>\\n                                            <span t-field=\\"line.product_uom_id\\" groups=\\"uom.group_uom\\"/>\\n                                        </div>\\n                                    </td>\\n                                    <td t-if=\\"update_dates\\" class=\\"text-end\\">\\n                                        <div class=\\"container\\">\\n                                          <div class=\\"mb-3\\">\\n                                            <div class=\\"input-group date\\">\\n                                                <input type=\\"text\\" class=\\"form-control datetimepicker-input o-purchase-datetimepicker text-end\\" t-att-data-access-token=\\"order.access_token\\" t-att-data-order-id=\\"order.id\\" t-att-data-line-id=\\"line.id\\" t-att-data-value=\\"line.date_planned.isoformat()\\"/>\\n                                            </div>\\n                                          </div>\\n                                        </div>\\n                                    </td>\\n                                    <td t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <div t-field=\\"line.price_unit\\" class=\\"text-end\\"/>\\n                                    </td>\\n                                    <td t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <span t-out=\\"', '.join(map(lambda x: (x.name), line.tax_ids))\\"/>\\n                                    </td>\\n                                    <td t-if=\\"display_price_and_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <div t-field=\\"line.discount\\" class=\\"text-end\\"/>\\n                                    </td>\\n                                    <td class=\\"text-end\\" t-if=\\"not update_dates and order.state == 'purchase'\\">\\n                                        <span class=\\"oe_order_line_price_subtotal\\" t-field=\\"line.price_subtotal\\"/>\\n                                    </td>\\n                                </t>\\n                                <t t-if=\\"line.display_type in ('line_section', 'line_subsection')\\">\\n                                    <td colspan=\\"99\\">\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                    <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                    <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                                </t>\\n                                <t t-if=\\"line.display_type == 'line_note'\\">\\n                                    <td colspan=\\"99\\">\\n                                        <span t-field=\\"line.name\\"/>\\n                                    </td>\\n                                </t>\\n                            </tr>\\n                            <t t-if=\\"current_section and (line_last or filtered_lines[line_index+1].display_type in ('line_section', 'line_subsection')) and order.state == 'purchase'\\">\\n                                <tr class=\\"is-subtotal text-end\\">\\n                                    <td colspan=\\"99\\">\\n                                        <strong class=\\"mr16\\">Subtotal</strong>\\n                                        <span t-esc=\\"current_subtotal\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}\\"/>\\n                                    </td>\\n                                </tr>\\n                            </t>\\n                        </t>\\n                    </tbody>\\n                </table>\\n              </div>\\n\\n              <div id=\\"total\\" t-if=\\"order.state == 'purchase'\\" class=\\"row\\" name=\\"total\\" style=\\"page-break-inside: avoid;\\">\\n                  <div t-attf-class=\\"#{'col-4' if report_type != 'html' else 'col-sm-7 col-md-5'} ms-auto\\">\\n                      <t t-call=\\"purchase.purchase_order_portal_content_totals_table\\"/>\\n                  </div>\\n              </div>\\n          </section>\\n\\n          <section id=\\"terms\\" class=\\"mt-5\\" t-if=\\"order.note\\">\\n              <h3 class=\\"\\">Terms &amp; Conditions</h3>\\n              <hr class=\\"mt-0 mb-1\\"/>\\n              <em t-field=\\"order.note\\"/>\\n          </section>\\n\\n          <section class=\\"mt-5\\" t-if=\\"order.payment_term_id\\">\\n              <h3 class=\\"\\">Payment terms</h3>\\n              <hr class=\\"mt-0 mb-1\\"/>\\n              <span t-field=\\"order.payment_term_id\\"/>\\n          </section>\\n      </div>\\n  </t>"}	<?xml version="1.0"?>\n<t name="Purchase Order Portal Content" t-name="purchase.purchase_order_portal_content">\n      <!-- Intro -->\n      <div id="introduction" class="mt-5 mt-lg-0 pb-2 pt-0">\n        <h2 class="my-0">\n          <t t-if="order.state in ['draft', 'sent']">Request for Quotation</t>\n          <t t-else="1">\n            Purchase Order\n          </t>\n          <em t-esc="order.name"/>\n        </h2>\n      </div>\n\n      <div>\n          <!-- Informations -->\n          <div id="informations">\n              <div class="row" id="po_date">\n                  <div class="mb-3 col-6">\n                    <t t-if="order.state in ['draft', 'sent']">\n                      <strong>Request For Quotation Date:</strong>\n                    </t>\n                    <t t-if="order.state in ['purchase', 'cancel']">\n                      <strong>Order Date:</strong>\n                    </t>\n                    <span t-field="order.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>\n                  </div>\n              </div>\n              <div class="row">\n                  <div class="col-lg-6">\n                    <strong class="d-block mb-1">From:</strong>\n                    <address t-field="order.company_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                    <t t-if="order.date_approve">\n                      <strong>Confirmation Date:</strong> <span t-field="order.date_approve" t-options="{&quot;widget&quot;: &quot;date&quot;}"/><br/>\n                    </t>\n                    <div t-att-class="'d-inline' if order.date_planned else 'd-none'">\n                      <strong>Receipt Date:</strong><span class="ms-1" t-field="order.date_planned" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>\n                    </div>\n                  </div>\n              </div>\n\n              <t t-set="invoices" t-value="[i for i in order.invoice_ids if i.state not in ['draft', 'cancel']]"/>\n              <div t-if="invoices" class="row">\n                  <div class="col">\n                      <strong class="d-block mb-1">Invoices</strong>\n                      <ul class="list-group mb-4">\n                          <t t-foreach="invoices" t-as="i">\n                              <t t-set="report_url" t-value="i.get_portal_url(report_type='pdf', download=True)"/>\n                              <div class="d-flex flex-wrap align-items-center justify-content-between">\n                                  <div>\n                                      <a t-att-href="report_url">\n                                          <span t-esc="i.name"/>\n                                      </a>\n                                      <div class="small d-lg-inline-block">Date: <span class="text-muted" t-field="i.invoice_date"/></div>\n                                  </div>\n                                  <span t-if="i.payment_state in ('paid', 'in_payment')" class="badge rounded-pill text-bg-success small"><i class="fa fa-fw fa-check"/>Paid</span>\n                                  <span t-elif="i.payment_state == 'reversed'" class="badge rounded-pill text-bg-success small"><i class="fa fa-fw fa-check"/>Reversed</span>\n                                  <span t-else="" class="small badge rounded-pill text-bg-primary"><i class="fa fa-fw fa-clock-o"/>Waiting Payment</span>\n                              </div>\n                          </t>\n                      </ul>\n                  </div>\n              </div>\n          </div>\n\n          <section id="details" style="page-break-inside: auto;" class="mt32">\n              <h3 id="details">Pricing</h3>\n\n              <div class="table-responsive">\n                <table t-att-data-order-id="order.id" t-att-data-token="order.access_token" class="table table-sm" id="purchase_order_table">\n                    <t t-set="display_price_and_taxes" t-value="not update_dates and order.state == 'purchase'"/>\n                    <thead class="bg-100">\n                        <tr>\n                            <th class="text-start">Products</th>\n                            <th class="text-end">Quantity</th>\n                            <th t-if="update_dates" class="text-end">Scheduled Date</th>\n                            <th t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">Unit Price</th>\n                            <th t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                <span>Taxes</span>\n                            </th>\n                            <th t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">Disc.%</th>\n                            <th class="text-end" t-if="display_price_and_taxes">\n                                <span>Amount</span>\n                            </th>\n                        </tr>\n                    </thead>\n                    <tbody class="purchase_tbody">\n\n                          <t t-set="current_subtotal" t-value="0"/>\n                          <t t-set="filtered_lines" t-value="order.order_line.filtered(lambda l: l.display_type or l.product_qty != 0)"/>\n\n                          <t t-foreach="filtered_lines" t-as="line">\n\n                              <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>\n\n                            <tr t-att-class="'fw-bolder o_line_section' if line.display_type == 'line_section' else 'fw-bold o_line_subsection' if line.display_type == 'line_subsection' else 'fst-italic text-break o_line_note' if line.display_type == 'line_note' else ''">\n                                <t t-if="not line.display_type">\n                                    <td id="product_name" class="d-flex">\n                                        <img t-att-src="line.product_id.image_128 and image_data_uri(line.product_id.image_128) or '/web/static/img/placeholder.png'" alt="Product" class="d-none d-lg-inline o_purchase_portal_product_image"/>\n                                        <span t-field="line.name"/>\n                                    </td>\n                                    <td class="text-end">\n                                        <div id="quote_qty">\n                                            <span t-field="line.product_qty"/>\n                                            <span t-field="line.product_uom_id" groups="uom.group_uom"/>\n                                        </div>\n                                    </td>\n                                    <td t-if="update_dates" class="text-end">\n                                        <div class="container">\n                                          <div class="mb-3">\n                                            <div class="input-group date">\n                                                <input type="text" class="form-control datetimepicker-input o-purchase-datetimepicker text-end" t-att-data-access-token="order.access_token" t-att-data-order-id="order.id" t-att-data-line-id="line.id" t-att-data-value="line.date_planned.isoformat()"/>\n                                            </div>\n                                          </div>\n                                        </div>\n                                    </td>\n                                    <td t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">\n                                        <div t-field="line.price_unit" class="text-end"/>\n                                    </td>\n                                    <td t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                        <span t-out="', '.join(map(lambda x: (x.name), line.tax_ids))"/>\n                                    </td>\n                                    <td t-if="display_price_and_taxes" t-attf-class="text-end {{ 'd-none d-sm-table-cell' if report_type == 'html' else '' }}">\n                                        <div t-field="line.discount" class="text-end"/>\n                                    </td>\n                                    <td class="text-end" t-if="not update_dates and order.state == 'purchase'">\n                                        <span class="oe_order_line_price_subtotal" t-field="line.price_subtotal"/>\n                                    </td>\n                                </t>\n                                <t t-if="line.display_type in ('line_section', 'line_subsection')">\n                                    <td colspan="99">\n                                        <span t-field="line.name"/>\n                                    </td>\n                                    <t t-set="current_section" t-value="line"/>\n                                    <t t-set="current_subtotal" t-value="0"/>\n                                </t>\n                                <t t-if="line.display_type == 'line_note'">\n                                    <td colspan="99">\n                                        <span t-field="line.name"/>\n                                    </td>\n                                </t>\n                            </tr>\n                            <t t-if="current_section and (line_last or filtered_lines[line_index+1].display_type in ('line_section', 'line_subsection')) and order.state == 'purchase'">\n                                <tr class="is-subtotal text-end">\n                                    <td colspan="99">\n                                        <strong class="mr16">Subtotal</strong>\n                                        <span t-esc="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}"/>\n                                    </td>\n                                </tr>\n                            </t>\n                        </t>\n                    </tbody>\n                </table>\n              </div>\n\n              <div id="total" t-if="order.state == 'purchase'" class="row" name="total" style="page-break-inside: avoid;">\n                  <div t-attf-class="#{'col-4' if report_type != 'html' else 'col-sm-7 col-md-5'} ms-auto">\n                      <t t-call="purchase.purchase_order_portal_content_totals_table"/>\n                  </div>\n              </div>\n          </section>\n\n          <section id="terms" class="mt-5" t-if="order.note">\n              <h3 class="">Terms &amp; Conditions</h3>\n              <hr class="mt-0 mb-1"/>\n              <em t-field="order.note"/>\n          </section>\n\n          <section class="mt-5" t-if="order.payment_term_id">\n              <h3 class="">Payment terms</h3>\n              <hr class="mt-0 mb-1"/>\n              <span t-field="order.payment_term_id"/>\n          </section>\n      </div>\n  </t>\n\n  	f	t	2026-11-09 19:12:43.169083	2026-11-09 19:12:43.169083	f
