o user linked\\" domain=\\"[('company_ids', 'in', company_id)]\\" context=\\"{                                                     'default_create_employee_id': id,                                                     'default_name': name,                                                     'default_phone': work_phone,                                                     'default_mobile': mobile_phone,                                                     'default_login': work_email,                                                     'default_partner_id': work_contact_id,                                                     'search_default_filter_no_share': 1,                                                 }\\" widget=\\"many2one_avatar_user\\" groups=\\"!base.group_erp_manager\\" options=\\"{'no_open': True}\\"/>\\n                                            <span invisible=\\"not user_id or is_user_active\\">\\n                                                (User is Inactive)\\n                                            </span>\\n                                            <field name=\\"tz\\" required=\\"id\\"/>\\n                                        </div>\\n                                    </group>\\n                                    <group name=\\"managers\\" string=\\"Approvers\\">\\n                                        <field name=\\"hr_responsible_id\\" widget=\\"many2one_avatar_user\\"/>\\n                                    </group>\\n                                    <group name=\\"application_group\\" string=\\"Application Settings\\" invisible=\\"1\\"/>\\n                                    <group string=\\"Attendance/Point of Sale\\" name=\\"identification_group\\">\\n                                        <field name=\\"pin\\" string=\\"PIN Code\\"/>\\n                                        <label for=\\"barcode\\"/>\\n                                        <div class=\\"o_row\\">\\n                                            <field na