ment\\">\\n                    <li style=\\"font-size: 13px;\\">\\n                        <a t-out=\\"document.ir_attachment_id.name\\" t-att-href=\\"object.get_portal_url('/document/' + str(document.id))\\" t-att-target=\\"target\\"/>\\n                    </li>\\n                </t>\\n            </ul>\\n        </t>\\n        <br/>\\n        Do not hesitate to contact us if you have any questions.\\n        <t t-if=\\"not is_html_empty(object.user_id.signature)\\" data-o-mail-quote-container=\\"1\\">\\n            <div data-o-mail-quote=\\"1\\">--<br data-o-mail-quote=\\"1\\"/><t t-out=\\"object.user_id.signature or ''\\" data-o-mail-quote=\\"1\\">Mitchell Admin</t></div>\\n        </t>\\n    </p>\\n<t t-if=\\"hasattr(object, 'website_id') and object.website_id\\">\\n    <div style=\\"margin: 0px; padding: 0px;\\">\\n        <table width=\\"100%\\" style=\\"color: #454748; font-size: 12px; border-collapse: collapse; white-space: nowrap;\\">\\n            <tr style=\\"border-bottom: 2px solid #dee2e6;\\">\\n                <td style=\\"width: 150px;\\"><span style=\\"font-weight:bold;\\">Products</span></td>\\n                <td/>\\n                <td width=\\"15%\\" align=\\"center\\"><span style=\\"font-weight:bold;\\">Quantity</span></td>\\n                <td width=\\"20%\\" align=\\"right\\">\\n                    <span style=\\"font-weight:bold;\\">\\n                        <t t-if=\\"hasattr(object, 'website_id') and object.website_id.show_line_subtotals_tax_selection == 'tax_excluded'\\">\\n                            Tax Excl.\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            Tax Incl.\\n                        </t>\\n                    </span>\\n                </td>\\n            </tr>\\n        </table>\\n        <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n        <t t-foreach=\\"object.order_line\\" t-as=\\"line\\">\\n            <t t-set=\\"line_subtotal\\" t-value=\\"              